(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["multimodal"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-vprune-prelm"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-1\">一 · 一次预填雪崩：问题从显存侧先爆</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-2\">二 · 它到底削减了什么：预填 FLOPs 与 KV 显存的双线性</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-3\">三 · 机制顺序即边界：打分发生在预填之前意味着什么</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-4\">四 · 不解决什么：三类它管不到的问题</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-5\">五 · 适用边界的量化表达：k 的两侧都是悬崖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-6\">六 · 预填前的单级剪枝：它救的是哪类故障，又在哪类流量上失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-7\">七 · 打分器的输入形态与分数语义</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-8\">八 · top-k 选择与空间顺序保持</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-9\">九 · 投影与预填：收益真正兑现的位置</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-10\">十 · KV cache 分配：显存账本的第二笔</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-11\">十一 · 全链路代价分解与失败模式的落点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-12\">十二 · 批调度视角下的步骤时序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-13\">十三 · 边界条件：打分器与任务解耦后的失效面</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-14\">十四 · 选择算子：从分数向量到保留集合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-15\">十五 · 空间顺序保持：位置编码一致性的形式化</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-16\">十六 · 打分器归一化：防止单一尺度主导选择</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-17\">十七 · 伪代码：可实现的预填前剪枝</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-18\">十八 · 预算 $k$ 的敏感性与失败模式推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-19\">十九 · 与其他缩减路径的公式级分野</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-20\">二十 · 请求形态：什么样的流量吃到剪枝收益</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-21\">二十一 · 长度分布：固定 k 把分布压成一条线，也压掉了方差信息</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-22\">二十二 · 并发与批大小：k 缩小了单请求足迹，抬高了并发上限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-23\">二十三 · SLO 由 k 与文本长度共同决定，单一 SLO 覆盖不了全部流量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-24\">二十四 · 负载不对时的三种崩法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-25\">二十五 · 配方落地：把 k 当成路由参数而不是常量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-26\">二十六 · 固定预算 k 的负载适配边界与失效形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-27\">二十七 · 硬件档位：谁在决定下限</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-28\">二十八 · 并行拓扑：k 对齐带来的批调度红利</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-29\">二十九 · 量化方案：与语言模型精度对齐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-30\">三十 · KV 策略：按 k 分配与预算的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-31\">三十一 · 调度参数：可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-32\">三十二 · 固定 k 的部署边界：打分器失配、批对齐假象与显存账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-33\">三十三 · 预填侧的系统账：k 决定了什么在崩</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-34\">三十四 · 带宽与通信：省下的是 KV 流量，不是权重流量</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-35\">三十五 · 功耗与规模上限：谁先撞墙</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-36\">三十六 · 失败模式在系统指标上的投影</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-37\">三十七 · 容量规划中的 k 与批的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-38\">三十八 · k 一旦固定，系统瓶颈就从算力转到调度与尾延迟</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-39\">三十九 · 精度塌陷的三种签名与定位手段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-40\">四十 · OOM 的真实来源：不是 k，而是批内长度方差</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-41\">四十一 · 批抖动与路由不均：固定 k 掩盖不了的调度病</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-42\">四十二 · 尾延迟尖刺：打分器与视觉前向的耦合点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-43\">四十三 · 监控指标体系与回滚判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-44\">四十四 · 把诊断嵌进数据流：一个可落地的判断</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-45\">四十五 · 边界与失效：打分器解耦带来的三类系统性故障</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-46\">四十六 · 同族算法的三条分界线</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-47\">四十七 · 决策表：按约束选算法</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-48\">四十八 · 适用条件的量化边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-49\">四十九 · 组合而非替代：与量化、缓存的叠加顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-vprune-prelm-sec-50\">五十 · 迁移判断：什么情况下换算法</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:482px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 482.0 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">视觉编码器输出 N 个 patch token</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">轻量打分器计算每 token 的重要性分数</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按预算 k 做 top-k 选择并保持空间顺序</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">保留 token 经投影层进入 LLM 预填</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"400.0\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">KV cache 仅按 k 个视觉 token 分配</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-vprune-prelm-sec-1\">一 · 一次预填雪崩：问题从显存侧先爆</h3>\n<p>把场景钉死在一个具体的线上事故形态上。某多模态问答服务接入高分辨率票据识别：单张扫描件经视觉编码器切成数千个 patch token，直接拼进 LLM 预填序列。上线初期用小图压测一切正常，真实流量进来后出现两类症状：一是预填阶段显存瞬时冲高，KV cache 按全量视觉 token 分配，单请求占用远超容量规划时的估算，连续批处理被迫缩小批大小，吞吐塌陷；二是尾延迟抖动，长图请求把批内序列长度拉长，短请求被拖在同一批里等长图预填完成。运维侧的直觉是加卡，但加卡只缓解了并发数，没有改变单请求的预填成本结构——FLOPs 与 KV 显存都随视觉 token 数 N 线性增长，而 N 由图像分辨率决定，不由业务并发决定。</p>\n<p>这个事故的关键在于：瓶颈不在解码，而在预填。解码阶段的 token 生成是逐位的、受带宽约束；预填是一次性的大矩阵乘，受算力与显存容量双重约束。视觉 token 恰恰全部堆在预填入口，它们不产生任何自回归输出，却实打实地占用 KV cache 的显存页。工程判断因此很直接：如果能在视觉 token 进入 LLM 之前就把数量从 N 压到 k，预填 FLOPs 与 KV 显存就同时按 k/N 的比例缩减，而不是等到中间层再想办法。这正是本算法所处的位置——剪枝完全发生在预填之前，是数据流上最早、也最省事的一刀。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-2\">二 · 它到底削减了什么：预填 FLOPs 与 KV 显存的双线性</h3>\n<p>把代价写清楚，才能划边界。设视觉编码器输出 N 个 patch token，每个 token 经投影层后维度为 d，LLM 预填对视觉段的注意力计算量随 N 的平方（自注意力）与 N·d（投影与 MLP）增长；KV cache 的视觉部分显存则与 N 成正比。剪枝保留 k 个 token 后，两条曲线同时换自变量：</p>\n<div class=\"formula\">$$\\text{keep}=\\text{TopK}\\big(s_i\\big)_{i=1}^{N},\\quad \\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>这条比值是整个算法的收益上限，也是它的责任边界。收益是双重的：显存侧直接按 k/N 缩，预填算力侧因序列变短而下降，且批调度可以把批内序列长度按固定 k 对齐，减少长短请求互相拖累。代价同样明确：打分器是轻量启发式，与下游任务解耦，它不知道这张图里哪个 patch 是发票金额、哪个是印章边缘。于是它削减的是“数量”，不是“冗余”——被删的 token 里可能恰好含有任务关键信息。这个区别决定了后面所有失败模式：算法优化的是预填成本，不是识别精度，两者在细粒度任务上会正面冲突。</p>\n<p>一个具体例子足以说明边界。同一套固定预算 k，用在整图场景问答（“这张图里有几个人”）上，答案依赖全局布局，删掉一半 patch 后语义仍可恢复；用在票据金额识别上，金额数字往往只占极小区域，其 patch 的特征范数未必突出，打分器按范数排序时这些 token 排在尾部被整批删除，整图问答指标不掉，局部字段识别却系统性失败。这不是调参能掩盖的噪声，而是打分信号与任务目标之间的结构性错位。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-3\">三 · 机制顺序即边界：打分发生在预填之前意味着什么</h3>\n<p>按数据流把机制走一遍，边界自然浮现。视觉编码器输出 N 个 patch token；轻量打分器对每个 token 特征 $\\mathbf{z}_i$ 计算分数 $s_i=f(\\mathbf{z}_i)$，$f$ 可取特征范数、注意力权重或多样性度量；按预算 k 取 top-k 并保持空间顺序；保留 token 经投影层进入 LLM 预填；KV cache 只按 k 个视觉 token 分配。选择规则写作：</p>\n<div class=\"formula\">$$S=\\mathrm{TopK}\\big(\\{s_i\\}_{i=1}^{N},\\,k\\big),\\quad s_i=f(\\mathbf{z}_i)$$</div>\n<p>“预填之前”这个位置带来三个不可替代的性质。第一，无需训练：打分器是轻量算子，不依赖任务标注，可与任意视觉编码器组合部署，这对训练-free 的多模态服务是硬需求——换编码器不必重训剪枝模块。第二，收益直接：剪枝发生在 LLM 之外，削减的是进入解码器的输入规模，不涉及中间层改造，也不构造重构基、不计算重构误差，因此没有额外的重构前向开销。第三，代价也来自这个位置：打分器看不到 LLM 的注意力分布，也看不到任务损失，它只有编码器输出的静态特征。任务相关信息在预填之前尚未被语言侧“激活”，打分器无从借用。</p>\n<p>系统代价因此可以定位到硬件档位：视觉编码器前向与打分器决定视觉侧开销，LLM 侧因 k 缩减而降低显存与带宽压力。注意收益并不均摊——编码器前向的算力不随 k 变化，剪枝省的是 LLM 预填与 KV，不是视觉主干。若某服务视觉编码器本身已是瓶颈，这个算法的边际收益会被压缩。这就是适用边界的第一条：它适用于 LLM 侧预填与显存吃紧、视觉编码器相对轻的服务，而不是视觉侧本身超载的场景。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-4\">四 · 不解决什么：三类它管不到的问题</h3>\n<p>划清“不解决”比罗列“解决”更有工程价值。第一，它不解决细粒度保真。打分器与下游任务解耦，OCR、小目标检测这类依赖局部高分辨率细节的任务，关键 token 的分数未必高，top-k 会系统性误删。算法层面没有任务相关信号可用，只能靠上调 k 或换任务相关打分器来缓解，而这两条都削弱了“训练-free + 固定预算”的原始优势。第二，它不解决图像复杂度自适应。固定预算 k 对简单图过度保留、对复杂图保留不足：简单图本可压到更小 k，复杂图需要更大 k，但算法一视同仁。结果是批内序列长度虽对齐、精度方差却大，单一 SLO 难以覆盖全部流量形态。第三，它不解决空间一致性之外的顺序风险——top-k 后必须保持空间顺序，否则位置编码与视觉 token 顺序错位，模型输出出现空间关系错误，且这类错误不易被离线聚合指标发现，因为整图级指标可能仍然正常。</p>\n<p>还要明确它与相邻方案的职责分界。与近似误差引导压缩相比，本算法不构造重构基、不算重构误差，用一次性启发式选择换取零训练成本与零重构开销，代价是选择质量上限受打分器与任务相关性约束。与双阶段统一缩减相比，它只在 LLM 之前设一级剪枝，不在中间层再缩减，因此不会与层内注意力模式耦合，也不会引入跨阶段的调度复杂度。换句话说，它是一把“入口处的粗刀”，不是“层内的细刀”。把细粒度保真寄望于它，是用错了工具。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-5\">五 · 适用边界的量化表达：k 的两侧都是悬崖</h3>\n<p>边界可以写成 k 的函数。k 过小，细粒度任务失效，因为关键 token 被删的概率随 k/N 下降而上升；k 过大，收益消失，$M_{\\text{KV}}^{\\text{vis}}/M_{\\text{KV}}^{\\text{full}}$ 趋近 1，预填 FLOPs 回到全量水平，剪枝只剩打分器的额外开销。规模上限由打分器与任务的相关性决定：相关性高，k 可以压得更低而精度不塌；相关性低，k 必须留足余量，收益被侵蚀。工程上应把 k 当作按任务类型分档的配置项，而不是全局常量——票据类任务上调 k 或改用任务相关打分，整图问答类任务可下压 k。</p>\n<p>稳定性技巧也要落进边界描述里。打分器需对特征尺度做归一化，否则范数会主导选择，把高范数但语义无关的 token 留下、把低范数但关键的 token 删掉；top-k 后保持空间顺序是硬约束，破坏它引入的是位置编码层面的错误，而非精度层面的渐变。负载配方上，请求形态为高分辨率单图或多图问答，批大小可按固定 k 对齐序列长度从而便于批调度，SLO 由 k 与文本长度共同决定——这意味着容量规划要把 k 作为一等参数，而不是把视觉 token 数当作不可控输入。量化可与语言模型精度对齐，KV cache 按 k 个视觉 token 分配，这两条让显存预算在部署前就可算，而不是上线后被长图请求打穿。</p>\n<p>最后落到一个工程判断上：这个算法的正确用法是把它当作预填入口的“成本闸门”，先按任务类型定 k 档位、按特征尺度校准打分器、按空间顺序约束选择输出，再用整图指标与局部字段指标分别验收。若局部指标出现系统性塌陷，说明 k 档位或打分器与任务的相关性不足，此时应上调 k 或替换打分信号，而不是在 LLM 侧继续加卡——加卡改变不了单请求的预填成本结构，只会把同一场雪崩推迟到下一个流量高峰。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-6\">六 · 预填前的单级剪枝：它救的是哪类故障，又在哪类流量上失效</h3>\n<p>一次线上事故足以说明这个算法的靶心在哪：某多模态服务上线高分辨率票据问答，单图视觉 token 达数千，预填阶段序列长度被图像撑爆，KV cache 按全量视觉 token 分配，显存水位随并发线性抬升，最终触发抢占与请求排队，P99 延迟出现阶跃式恶化。根因不是解码慢，而是<b>预填算力与 KV 显存随 N 线性膨胀</b>，而服务又没有任务相关的重要性信号可用——模型是训练-free 接入的，视觉编码器随时可换。该算法正是针对这一形态：在视觉编码器输出端用轻量打分做一次性 top-k，只把 k 个 token 送进 LLM，剪枝完全发生在预填之前，因此削减的是预填 FLOPs 与 KV 显存本身，而不是事后补救。选择规则为</p>\n<div class=\"formula\">$$S=\\mathrm{TopK}\\big(\\{s_i\\}_{i=1}^{N},\\,k\\big),\\quad s_i=f(\\mathbf{z}_i),\\quad \\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>其中 $\\mathbf{z}_i$ 为第 i 个 patch token 特征，$f$ 可取特征范数、注意力或多样性打分。代价结构随之改变：预填 FLOPs 与视觉 KV 显存按 k 而非 N 增长，批调度可按固定 k 对齐序列长度，硬件压力从 LLM 侧前移到视觉编码器前向与打分器——后者是轻量算子，可与任意编码器组合、无需训练。但边界也在这里：打分器与下游任务解耦，细粒度 OCR 与小目标的 token 分数偏低，被 top-k 系统性删除，表现为整图问答正常、局部识别稳定失败；固定预算 k 对简单图过度保留、对复杂图保留不足，批内长度虽对齐，精度方差却大，单一 SLO 难以覆盖全部流量。下表给出失效条件与工程对策。</p>\n<table class=\"mini\"><thead><tr><th>失效条件</th><th>系统表现</th><th>对策</th></tr></thead><tbody><tr><td>细粒度 OCR／小目标</td><td>局部识别系统性错漏</td><td>按任务上调 k，或换任务相关打分</td></tr><tr><td>固定预算遇简单图</td><td>过度保留，收益被吃掉</td><td>按图像复杂度分档 k，牺牲批对齐</td></tr><tr><td>top-k 打乱空间顺序</td><td>位置编码错位，空间关系错误</td><td>选择后恢复原始顺序</td></tr><tr><td>特征尺度未归一化</td><td>范数主导选择，多样性丢失</td><td>打分前做尺度归一化</td></tr></tbody></table>\n<p>还需明确它不解决什么：它不构造重构基、不算重构误差，因此不具备近似误差引导压缩那类可解释的重建保证；它只在 LLM 之前设一级剪枝，不在中间层再缩减，故对解码阶段的带宽压力无能为力。规模上限由打分器与任务的相关性决定——k 过小则细粒度任务失效，k 过大则收益消失，固定预算对图像复杂度不敏感是扩展的主要瓶颈。工程判断很直接：训练-free、编码器可替换的多模态服务适合用它兜住预填成本；若流量以文档细读为主，应把 k 与任务类型绑定，而不是迷信一个全局常数。</p>\n<h3 id=\"alg-vprune-prelm-sec-7\">七 · 打分器的输入形态与分数语义</h3>\n<p>按数据流走，第一步发生在视觉编码器最后一层输出之后、投影层之前。输入是一个形状为 <span class=\"inline-math\">N×d</span> 的 patch token 张量 <span class=\"inline-math\">Z</span>，其中 <span class=\"inline-math\">N</span> 是 patch 网格展开后的 token 数（高分辨率输入可达数千），<span class=\"inline-math\">d</span> 是编码器隐维。输出是长度 <span class=\"inline-math\">N</span> 的分数向量 <span class=\"inline-math\">s</span>。这一步不改变张量布局，也不触发与 LLM 的任何交互，是整个流程中唯一“看全图”的环节。</p>\n<p>分数语义决定了后续 top-k 的行为。特征范数打分器取 <span class=\"inline-math\">s_i=‖z_i‖₂</span>，其隐含假设是激活强度大的 patch 承载更多语义；注意力打分器取编码器某一层（通常是最后几层）的 CLS-to-patch 或 patch-to-patch 注意力质量并沿头维求和；多样性打分器则在特征空间做聚类或行列式点过程式的子集选择，追求保留 token 之间的覆盖度而非单点强度。三者共同的工程约束是：打分器必须是轻量算子，其开销相对视觉编码器前向可忽略，否则剪枝省下的预填算力会被打分本身吃掉。</p>\n<p>代价在这里第一次显形。打分器引入一次额外的 <span class=\"inline-math\">O(N·d)</span> 归约（范数）或 <span class=\"inline-math\">O(N²)</span> 级的相似度计算（多样性），后者在 <span class=\"inline-math\">N</span> 达到数千时不可忽视。注意力打分器若需回读中间层激活，还会带来一次额外的显存读写。因此工程上更常见的是范数类打分：它只需对已驻留的编码器输出做一次行归约，带宽代价约等于把 <span class=\"inline-math\">Z</span> 读一遍。具体例子：一张切分为 4096 个 patch token、隐维 1024 的图像，范数打分需读 4096×1024 个半精度元素，量级在数 MB，相对编码器前向的算力占比很小；而多样性打分若做全对相似度，则需构造 4096×4096 的中间矩阵，显存与带宽代价立刻跃升为瓶颈。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-8\">八 · top-k 选择与空间顺序保持</h3>\n<p>第二步是选择。输入是分数向量 <span class=\"inline-math\">s</span> 与预算 <span class=\"inline-math\">k</span>，输出是保留索引集合 <span class=\"inline-math\">S</span> 与按索引排序后的子张量 <span class=\"inline-math\">Z_S</span>。规则可写为：</p>\n<div class=\"formula\">$$S=\\mathrm{TopK}\\big(\\{s_i\\}_{i=1}^{N},\\,k\\big),\\quad s_i=f(\\mathbf{z}_i)$$</div>\n<p>关键在于 <span class=\"inline-math\">S</span> 的有序性。top-k 天然产出的是按分数降序排列的索引，而视觉编码器的位置编码是按 patch 网格的扫描顺序注入的。若直接把降序索引对应的 token 送入 LLM，位置编码与 token 的空间邻接关系错位，模型仍能回答整图层面的问题，但涉及“左上角”“右侧第二个”这类空间指代时输出会系统性出错，且这种错误在常规图文匹配指标上几乎不可见。因此选择之后必须增加一次按原始索引的重排（scatter 或 gather with sorted indices），把 <span class=\"inline-math\">Z_S</span> 恢复为扫描序。这一步是纯索引操作，代价是一次 <span class=\"inline-math\">k×d</span> 的显存搬运，量级远小于打分，但它是正确性开关而非性能开关。</p>\n<p>top-k 本身的代价随 <span class=\"inline-math\">N</span> 增长。精确 top-k 需要对 <span class=\"inline-math\">N</span> 个分数做部分排序，在 GPU 上通常实现为分块基数选择或迭代阈值法，其耗时与 <span class=\"inline-math\">N</span> 近似线性但带有多个 kernel 启动开销。当 <span class=\"inline-math\">N</span> 为数千、<span class=\"inline-math\">k</span> 为数百时，这一段的绝对延迟在微秒到数十微秒量级，相对编码器前向的毫秒级开销可忽略；但若服务把批内多图拼成一个大 <span class=\"inline-math\">N</span> 做统一 top-k，选择就会跨图竞争预算，破坏每图固定 <span class=\"inline-math\">k</span> 的批调度假设。因此实现上按图独立选择、再拼批，是维持“批大小可按固定 <span class=\"inline-math\">k</span> 对齐序列长度”这一负载配方的前提。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-9\">九 · 投影与预填：收益真正兑现的位置</h3>\n<p>第三步，保留 token 经投影层进入 LLM 预填。输入是 <span class=\"inline-math\">k×d</span> 的视觉特征，输出是 <span class=\"inline-math\">k×d'</span> 的语言模型输入嵌入，与文本 token 嵌入拼接后构成预填序列。投影层通常是一个两层 MLP 或线性映射，其 FLOPs 与 <span class=\"inline-math\">k</span> 成正比，因此剪枝在这里第一次直接削减了计算量：预填阶段视觉部分的注意力与 FFN 开销随 <span class=\"inline-math\">k</span> 而非 <span class=\"inline-math\">N</span> 增长。</p>\n<p>把这一步的代价写清楚：设 LLM 隐维 <span class=\"inline-math\">d'</span>、层数 <span class=\"inline-math\">L</span>，视觉 token 参与的预填注意力与 FFN 计算量近似正比于 <span class=\"inline-math\">k·L·d'²</span>（忽略文本长度与二次项）。当 <span class=\"inline-math\">N</span> 为数千而 <span class=\"inline-math\">k</span> 为数百时，视觉侧预填 FLOPs 按比例下降一个量级，这是该算法最主要的吞吐收益来源。同时，预填阶段的激活显存与注意力中间缓冲也随序列长度缩减，长序列预填常见的分块调度压力随之缓解。</p>\n<p>具体例子：一张多图问答请求，四张图各 <span class=\"inline-math\">N=2048</span>、预算 <span class=\"inline-math\">k=256</span>，则进入 LLM 的视觉 token 从 8192 降到 1024。若文本侧为数百 token，预填序列长度从近万降到千余，预填延迟与首 token 延迟的视觉占比显著下降；反之若 <span class=\"inline-math\">k</span> 取到 1024，四图合计 4096，收益减半但仍成立。这里没有免费午餐：<span class=\"inline-math\">k</span> 的选择直接决定预填代价，而 <span class=\"inline-math\">k</span> 的合理性取决于图像内容复杂度，这正是固定预算的结构性弱点。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-10\">十 · KV cache 分配：显存账本的第二笔</h3>\n<p>第四步发生在解码开始之前：KV cache 仅按 <span class=\"inline-math\">k</span> 个视觉 token 分配。输入是预填完成后的序列布局，输出是每层每头为视觉位置预留的 K/V 槽位。比例关系为：</p>\n<div class=\"formula\">$$\\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>这笔账在长上下文、大并发下比预填 FLOPs 更致命。KV cache 显存正比于序列长度×层数×头数×头维×精度字节数，视觉 token 从 <span class=\"inline-math\">N</span> 降到 <span class=\"inline-math\">k</span> 意味着这部分显存按 <span class=\"inline-math\">k/N</span> 缩减。在连续批处理服务里，这直接换算成可并发的请求数：显存是批调度的硬约束，视觉 KV 缩减释放出的容量可以换成更大的批或更长的文本上下文。同时解码每步的 KV 读取带宽也随视觉位置数下降，解码吞吐受益。</p>\n<p>工程细节在于分配时机与碎片。视觉 KV 必须在预填时就按 <span class=\"inline-math\">k</span> 分配，而不是先按 <span class=\"inline-math\">N</span> 分配再释放，否则峰值显存不降反升。分页式 KV 管理下，<span class=\"inline-math\">k</span> 个视觉 token 占用的页数与文本 token 同构，因此批内序列长度对齐后页表布局规整，调度器可以用固定 <span class=\"inline-math\">k</span> 预估每请求的显存占用，做准入控制。具体例子：若每 token 每层 KV 占用为固定字节数，<span class=\"inline-math\">N=4096</span> 降到 <span class=\"inline-math\">k=512</span> 即视觉 KV 缩减为八分之一，在数十层、数十头的配置下释放出的显存足以让并发批提升数倍——这是定性结论，具体倍数取决于层头配置与文本长度占比。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-11\">十一 · 全链路代价分解与失败模式的落点</h3>\n<p>把五步串起来看代价分布：编码器前向与打分器是固定开销，不随 <span class=\"inline-math\">k</span> 变化；top-k 与重排是微秒级索引开销；投影与预填随 <span class=\"inline-math\">k</span> 线性；KV 显存与解码带宽随 <span class=\"inline-math\">k</span> 线性。因此整条链路的收益曲线在 <span class=\"inline-math\">k</span> 较小时最陡，随着 <span class=\"inline-math\">k</span> 增大迅速变平，而编码器与打分器的固定开销占比上升。这解释了规模上限：<span class=\"inline-math\">k</span> 过小则细粒度任务失效，<span class=\"inline-math\">k</span> 过大则收益消失，两端之间没有任务自适应的调节机制。</p>\n<p>三个失败模式各自落在不同步骤。细粒度 OCR 与小目标误删落在第二步：打分器与下游任务解耦，小目标 patch 的特征范数或注意力质量天然偏低，top-k 把它们删掉，整图问答指标正常而局部识别系统性失败。固定预算的精度方差落在第一与第二步之间：简单图过度保留、复杂图保留不足，批内序列长度虽因固定 <span class=\"inline-math\">k</span> 而对齐，精度方差却让单一 SLO 无法覆盖全部流量，容量规划只能按最复杂流量定 <span class=\"inline-math\">k</span>，简单流量白白付费。空间顺序错位落在第二步的重排环节：漏掉按原始索引重排，位置编码与 token 顺序错位，输出空间关系错误且离线指标难以发现。</p>\n<p>对应的稳定性技巧也按步骤归位：打分器对特征尺度做归一化（如按通道或按图做标准化）以避免范数主导选择，这是第一步的防护；top-k 后强制按原始索引 gather，这是第二步的防护；按任务类型上调 <span class=\"inline-math\">k</span> 或替换为任务相关打分器，这是跨步骤的策略调整。值得注意的是，任务相关打分器一旦引入，就不再是训练-free 的轻量启发式，而会滑向需要监督信号的压缩路线——本算法与近似误差引导压缩的分界正在此处：后者构造重构基并计算重构误差，本算法只做一次性启发式选择，不碰重构。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-12\">十二 · 批调度视角下的步骤时序</h3>\n<p>从服务调度看，这五步构成一个可流水化的阶段序列：编码器前向与打分可按图并行，top-k 与重排是图内局部操作，投影与预填进入 LLM 的批调度器，KV 分配发生在预填末尾。由于 <span class=\"inline-math\">k</span> 固定，调度器可以在请求到达时即预估视觉侧序列长度与 KV 占用，无需等编码器完成，这对准入控制与批成形有利。代价是预估与实际内容复杂度脱钩：调度器按固定 <span class=\"inline-math\">k</span> 分配的预算，对复杂图可能不足、对简单图可能过剩，过剩部分表现为显存与算力的静默浪费，不足部分表现为精度损失而非调度失败，因此不会触发任何告警。</p>\n<p>工程判断落在 <span class=\"inline-math\">k</span> 的选取策略上：单一全局 <span class=\"inline-math\">k</span> 适合流量同质、以整图理解为主的服务；若流量中混有 OCR 或小目标密集请求，应按请求类型分桶给不同 <span class=\"inline-math\">k</span>，并在桶内保持固定预算以维持批对齐。打分器归一化与索引重排是必须常开的两个开关，前者防止选择偏置，后者防止位置错位。至于打分器与任务的相关性上限，它决定了这套一次性剪枝能走多远——相关性越弱，<span class=\"inline-math\">k</span> 的下界就被精度约束抬得越高，收益空间越窄。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-13\">十三 · 边界条件：打分器与任务解耦后的失效面</h3>\n<p>一次性 top-k 选择把剪枝决策压在预填之前，代价是决策与下游任务彻底解耦。打分器 $f(\\mathbf{z}_i)$ 只看视觉编码器输出的特征范数、注意力或多样性，看不到 OCR 查询、小目标定位这类任务信号。细粒度文字笔画、远处小目标的 patch 特征范数往往偏低，在 top-k 中被系统性删除，整图问答仍正常，局部识别却稳定失败——这是该方案最典型的失效模式，且离线整图指标难以暴露。工程上应把 $k$ 按任务类型分档，OCR 与小目标流量走更大预算或换任务相关打分器，而不是用单一 $k$ 覆盖全部请求。</p>\n<p>固定预算对图像复杂度不敏感是规模扩展的主要瓶颈。简单图（大面积纯色背景、单一主体）用满 $k$ 属于过度保留，复杂图（密集文本、多目标）则保留不足；批内序列长度虽因固定 $k$ 而对齐、便于批调度，但精度方差随图像复杂度漂移，单一 SLO 无法覆盖全部流量。容量规划上应按流量中复杂图占比做加权，而非按平均 $k$ 估算。另一处隐蔽失效是 top-k 后未保持空间顺序：位置编码与视觉 token 顺序错位，模型输出出现空间关系错误，且不易被离线指标发现，必须在选择后显式按原 patch 索引重排。</p>\n<div class=\"formula\">$$\\text{keep}=\\text{TopK}\\big(s_i\\big)_{i=1}^{N},\\quad \\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>系统代价随 $k$ 而非 $N$ 线性增长：预填 FLOPs 与 KV 显存按 $k/N$ 比例缩减，视觉编码器前向与打分器开销则与 $N$ 绑定，构成不可压缩的固定成本——高分辨率下编码器本身可能成为延迟主项，此时继续压低 $k$ 收益递减。打分器还需对特征尺度做归一化，避免范数主导选择；量化可与语言模型精度对齐，KV cache 仅按 $k$ 个视觉 token 分配。规模上限由打分器与任务的相关性决定：$k$ 过小则细粒度任务失效，$k$ 过大则收益消失。</p>\n<h3 id=\"alg-vprune-prelm-sec-14\">十四 · 选择算子：从分数向量到保留集合</h3>\n<p>本算法的全部数学内容可以压缩成一条选择规则：给定视觉编码器输出的 N 个 patch token 特征 $\\{\\mathbf{z}_i\\}_{i=1}^{N}$，用打分器 $f$ 逐 token 计算标量分数 $s_i=f(\\mathbf{z}_i)$，再按预算 $k$ 取前 $k$ 个下标构成保留集合 $S$。写成集合形式即 $S=\\mathrm{TopK}(\\{s_i\\}_{i=1}^{N},k)$，等价地 $S=\\{i \\mid \\mathrm{rank}(s_i)\\le k\\}$，其中 $\\mathrm{rank}$ 是按分数降序排列后的位次。这条公式的工程含义不在 $\\mathrm{TopK}$ 本身，而在三个隐含约束：$f$ 必须与下游 LLM 解耦且足够便宜；$S$ 必须携带空间顺序信息；$k$ 必须是一个可在批内对齐的常数。三者共同决定了这个算子能否真正落地为预填前的一次性剪枝。</p>\n<p>逐项拆开看。$\\mathbf{z}_i$ 是编码器最后一层输出的 patch 特征，维度为 $d$，因此打分器的一次前向代价是 $O(N\\cdot d)$ 量级的逐元素运算，与编码器本身的 $O(N^2 d)$ 自注意力相比可以忽略——这正是“轻量”二字的量化依据。$f$ 的三种典型取法对应三种不同的重要性假设：特征范数 $\\|\\mathbf{z}_i\\|_2$ 假设能量大的 patch 承载更多语义；注意力打分取编码器某一层的注意力权重对 patch 的边际贡献；多样性打分则在特征空间中做子集选择，惩罚与已选 token 过于相似的候选。三者都不需要任何任务标签，因此天然满足训练-free 的前提。$k$ 是唯一的外部超参，也是全部收益与全部风险的来源。</p>\n<p>推导的关键一步在于把“保留比例”翻译成“资源比例”。设每个视觉 token 在 LLM 侧占用的 KV 显存为 $m$ 字节（由层数、头数、头维度与 KV 精度共同决定），则视觉部分 KV 显存为 $M_{\\text{KV}}^{\\text{vis}}=k\\cdot m$，全量送入时为 $M_{\\text{KV}}^{\\text{full}}=N\\cdot m$，两者相除消去 $m$ 得到</p>\n<div class=\"formula\">$$\\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>这一步之所以关键，是因为它说明显存收益与 $m$ 无关，只与保留比例 $k/N$ 成正比。换言之，无论 KV 用 FP8 还是 NVFP4 存储，剪枝带来的相对节省是同一个数；量化与剪枝在这条式子上是相乘而非相加的关系，二者可以叠加但不会互相替代。同理，预填阶段视觉 token 贡献的注意力 FLOPs 近似正比于 $k\\cdot(N_{\\text{txt}}+k)$（视觉 token 与文本 token 的交叉注意力加上视觉自注意力），当 $k\\ll N$ 时该量随 $k$ 线性增长而非随 $N$ 平方增长，这是预填延迟改善的来源。</p>\n<p>一个具体例子：某高分辨率文档图经编码器切出数千个 patch token，若全量送入，视觉 KV 显存在长文本问答下会成为批大小的硬约束；取 $k$ 为数百量级后，视觉 KV 占比降到十分之一以下，同一张 GPU 上可容纳的并发请求数随之上升，而预填阶段视觉自注意力的规模也从全量矩阵缩小到保留子集。代价是打分器看不到下游问题，若图中存在小字号表格，其 patch 特征范数往往不突出，会在 top-k 中被系统性剔除。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-15\">十五 · 空间顺序保持：位置编码一致性的形式化</h3>\n<p>$\\mathrm{TopK}$ 返回的是按分数排序的下标序列，而 LLM 需要的是按空间扫描顺序排列的 token 序列。若直接把排序后的 token 送入投影层，视觉位置编码将与实际二维布局错位，模型学到的“左上—右下”相对关系被破坏。因此实现上必须做一次重排：先得到保留集合 $S$，再按原始下标升序输出 $\\tilde{\\mathbf{z}}_j=\\mathbf{z}_{S_{(j)}}$，其中 $S_{(j)}$ 表示 $S$ 中第 $j$ 小的下标。这一步不改变集合内容，只改变顺序，代价是一次 $O(k\\log k)$ 的排序，相对于编码器前向可以忽略，但它是正确性约束而非性能优化。</p>\n<p>形式化地，设原始位置编码为 $\\mathbf{p}_i$（由 patch 的二维坐标决定），则送入 LLM 的第 $j$ 个视觉 token 必须携带 $\\mathbf{p}_{S_{(j)}}$ 而非 $\\mathbf{p}_j$。若实现中错误地使用了压缩后的连续位置 $j$，等价于对所有保留 token 做了一次非均匀的位置拉伸，模型输出会出现空间关系错误——例如把图中左右相邻的两个对象描述成上下关系。这类错误在整图问答的离线指标上往往不可见，因为语义内容仍在，只有涉及计数、相对位置、表格行列对齐的任务才会暴露，因此需要在部署前用专门的空间关系探针集验证。</p>\n<p>工程上的代价体现在批调度：由于每个请求的 $S$ 不同，重排后的 token 序列在语义上是“稀疏采样”的，但长度统一为 $k$，这使得批内序列长度天然对齐，无需按图像复杂度做变长 padding。这是本算法在服务侧的一个隐性收益——固定 $k$ 把视觉侧的不确定性吸收掉，让调度器只面对文本长度的变化。反过来，这也意味着简单图像与复杂图像被强制压到同一长度，简单图的冗余 token 被保留、复杂图的关键 token 被丢弃，批内精度方差由此产生。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-16\">十六 · 打分器归一化：防止单一尺度主导选择</h3>\n<p>若 $f$ 取特征范数，一个直接的问题是不同 patch 的特征尺度差异可能极大：高对比度边缘处的激活幅值远高于平坦区域，导致 top-k 几乎被纹理密集区域垄断，而语义关键但视觉平淡的区域（大片背景中的一个小物体）被挤出。推导上的修正是在打分前做尺度归一化，常用形式为</p>\n<div class=\"formula\">$$s_i=\\frac{\\|\\mathbf{z}_i\\|_2}{\\frac{1}{N}\\sum_{j=1}^{N}\\|\\mathbf{z}_j\\|_2}\\quad\\text{或}\\quad s_i=\\frac{\\|\\mathbf{z}_i-\\boldsymbol{\\mu}\\|_2}{\\sigma}$$</div>\n<p>前者按批内均值归一，后者按特征分布的均值 $\\boldsymbol{\\mu}$ 与标准差 $\\sigma$ 做标准化。归一化不改变 top-k 的相对次序吗？会改变——因为除以同一个常数不改变次序，但减去均值后，偏离主成分方向的 token 会获得更高分数，这正是多样性导向的选择。这一步的工程代价极小（一次归约），但它决定了打分器是否被单一尺度主导，属于必须实现而非可选的细节。</p>\n<p>更稳健的做法是把范数与多样性组合成分数 $s_i=\\alpha\\cdot\\tilde{\\|\\mathbf{z}_i\\|}+(1-\\alpha)\\cdot g(\\mathbf{z}_i,S_{&lt;i})$，其中 $g$ 度量候选与已选集合的最小距离，$\\alpha$ 控制能量与覆盖的权衡。这引入了一个贪心循环，复杂度从 $O(N)$ 升到 $O(Nk)$，在 $k$ 为数百、$N$ 为数千时仍是毫秒级以下的开销，但实现上需要注意向量化以避免 Python 层循环成为瓶颈。代价是打分器不再是纯逐元素算子，无法与编码器前向完全融合，需要一次独立的 kernel 启动。</p>\n<p>具体例子：一张包含大面积天空与一个小型飞行器的航拍图，纯范数打分会把 top-k 大量分配给云层纹理，飞行器所在 patch 因局部对比度低而落选，导致“图中有几架飞机”类问题失败；加入均值归一与多样性项后，飞行器 patch 因偏离全局特征分布而获得补偿分数，保留概率上升。这说明归一化不是数值稳定性的附属品，而是选择质量的一部分。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-17\">十七 · 伪代码：可实现的预填前剪枝</h3>\n<p>把上述约束落到可实现层面，核心流程可写成如下伪代码思路（以批处理为单位，$B$ 为批大小）：</p>\n<ul>\n<li>输入：编码器输出张量 <code>Z</code>，形状 $[B,N,d]$；预算 <code>k</code>；打分模式 <code>mode</code>。</li>\n<li>若 <code>mode</code> 为范数：<code>s = norm(Z, dim=-1)</code>，按 $d$ 维归约，形状 $[B,N]$。</li>\n<li>归一化：<code>s = s / mean(s, dim=-1, keepdim=True)</code>，逐样本归约，避免跨样本污染。</li>\n<li>选择：<code>idx = topk(s, k, dim=-1).indices</code>，形状 $[B,k]$，此时下标按分数降序。</li>\n<li>重排：<code>idx = sort(idx, dim=-1).values</code>，恢复原始空间扫描顺序。</li>\n<li> gather：<code>Zk = gather(Z, idx)</code>，形状 $[B,k,d]$，逐样本按 idx 取特征。</li>\n<li>投影：<code>H = proj(Zk)</code>，形状 $[B,k,d_{\\text{llm}}]$，与文本嵌入拼接后送入预填。</li>\n<li>KV 分配：按 $k$ 个视觉 token 预留 KV 页，文本部分按实际长度动态分配。</li>\n</ul>\n<p>这段伪代码里有三个容易出错的点。其一，归一化的归约维度必须是逐样本的 $N$ 维而非跨批的，否则批内一张高对比度图会压低另一张图的分数尺度，造成批间耦合。其二，<code>topk</code> 返回的下标顺序在多数框架中不保证稳定，必须显式 <code>sort</code>，否则同一输入在不同 kernel 实现下可能产生不同的 token 顺序，破坏可复现性。其三，<code>gather</code> 之后 <code>proj</code> 的矩阵乘规模从 $[B,N,d]\\times[d,d_{\\text{llm}}]$ 降为 $[B,k,d]\\times[d,d_{\\text{llm}}]$，这是投影层 FLOPs 的直接削减，也是预填总算力下降的一部分。</p>\n<p>代价核算：打分与 top-k 的显存开销是一次 $[B,N]$ 的分数张量与 $[B,k]$ 的下标张量，相对于 $[B,N,d]$ 的特征张量可以忽略；真正的显存节省发生在 KV 侧，即 $k$ 而非 $N$ 个视觉 token 的 KV 页。延迟上，剪枝本身增加了一次 kernel 启动与一次 gather，但在 $N$ 为数千量级时这部分开销远小于被削减的预填注意力计算。带宽上，投影层读取的特征量从 $N\\cdot d$ 降为 $k\\cdot d$，在 HBM 带宽受限的小批场景下这一项对首 token 延迟有实际贡献。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-18\">十八 · 预算 $k$ 的敏感性与失败模式推导</h3>\n<p>$k$ 的选择不是调参问题而是容量规划问题。由 $\\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$ 可知，$k$ 直接决定视觉 KV 的显存占用比例，进而决定在给定显存下可支撑的并发批大小；由预填 FLOPs 随 $k$ 线性增长可知，$k$ 也直接决定首 token 延迟的下界。两个约束共同给出可行域：$k$ 过大则收益消失，$k$ 过小则细粒度任务失效。后者可以用一个粗略的信息论直觉表述——保留 $k$ 个 token 相当于对原图做 $k/N$ 的采样率压缩，当图中关键信息（如一行小字）只占少数 patch 时，采样率低于该信息的占比就会导致不可恢复的丢失，且这种丢失是确定性的而非概率性的，因为 top-k 是硬选择。</p>\n<p>这解释了失败模式的系统性：打分器与下游任务解耦，意味着分数不含“这个问题关心哪个区域”的信息，于是细粒度 OCR 与小目标检测的 token 分数偏低而被删除，整图问答仍正常，局部识别任务系统性失败。这不是随机误差，无法通过多次采样平均消除，只能通过上调 $k$ 或换用任务相关打分来缓解。第二个失败模式是固定预算对图像复杂度不敏感：简单图过度保留浪费算力，复杂图保留不足损伤精度，批内序列长度虽因固定 $k$ 而对齐，精度方差却随图像复杂度分布而增大，单一 SLO 难以覆盖全部流量。</p>\n<p>工程判断上，可把 $k$ 设为与请求元数据挂钩的分段常数，例如按图像分辨率或文本问题类型分档，而非全局单一值；这样既保留了批内长度对齐的调度优势（同档请求共享 $k$），又缓解了复杂度不敏感的问题。代价是调度器需要按 $k$ 分桶组批，桶数增加会降低批的填充率，需要在分桶粒度与批效率之间做权衡。这一步的收益可以用一个简单的不等式衡量：分桶带来的精度提升必须大于填充率下降带来的吞吐损失，否则不如维持单一 $k$。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-19\">十九 · 与其他缩减路径的公式级分野</h3>\n<p>从公式形态上可以清楚看出本算法与相邻方法的差别。近似误差引导压缩构造重构基并最小化重构误差，其目标函数含 $\\|\\mathbf{Z}-\\mathbf{Z}\\mathbf{W}\\|$ 一类的重构项，选择依据是误差而非启发式分数；本算法的 $s_i=f(\\mathbf{z}_i)$ 不含任何重构项，也不构造基，因此没有矩阵分解的 $O(N d r)$ 开销，但也没有误差上界保证。双阶段统一缩减在 LLM 中间层再做一次缩减，其总保留量是两级预算的乘积 $k_1\\cdot k_2/N_1 N_2$；本算法只有一级，公式上就是单一的 $k/N$，实现更简单但缺少中间层的二次修正机会。</p>\n<p>这一分野决定了适用边界：当部署环境要求训练-free、视觉编码器可替换、且不希望引入重构基的存储与计算时，本算法的单级启发式是成本最低的路径；当任务对细粒度保真度要求高、且允许离线构造基或做轻量校准，则误差引导路径的公式提供了可优化的目标。两条路径在 KV 显存上的收益形式相同（都归结为保留比例），差别在于选择质量与实现复杂度。规模上限由打分器与任务的相关性决定：相关性高则 $k$ 可以压得更低而精度不塌，相关性低则 $k$ 必须留足余量，收益随之收窄。</p>\n<p>最后一个实现层面的判断：打分器应作为独立可替换模块暴露在服务配置中，而非硬编码进编码器封装。这样当流量从整图问答转向文档 OCR 时，可以在不改动编码器与 LLM 的前提下切换打分模式或上调 $k$，把任务相关性这个唯一不可训练-free 解决的变量交给运维侧按流量画像调整。这也是本算法在工程上真正的落点——公式只有一行，可调的是打分器与预算这两个旋钮。</p>\n<h3 id=\"alg-vprune-prelm-sec-20\">二十 · 请求形态：什么样的流量吃到剪枝收益</h3>\n<p>这套剪枝在数据流上只做一件事：在视觉编码器输出端把 N 个 patch token 一次性压到 k 个，然后才进 LLM 预填。因此它的收益结构完全由“N 与 k 的比值”和“视觉 token 在总序列里的占比”决定。适合它的请求形态有三个共同特征：单次请求携带高分辨率图像或多图、视觉 token 数远大于文本 token 数、任务对整图语义而非局部像素级细节负责。典型是文档版面问答、图表趋势描述、场景级视觉问答、多图对比。反过来，整页密集文字的 OCR、遥感小目标计数、UI 元素定位这类请求，视觉 token 里承载信息的那一小撮恰恰是打分器最容易判低分的，属于结构性不适配。</p>\n<p>把请求按“视觉占比”排序，可以得到一条清晰的收益曲线。设文本 token 数为 T、保留视觉 token 数为 k，则视觉部分在预填序列中的占比为</p>\n<div class=\"formula\">$$\\rho=\\frac{k}{k+T},\\qquad \\text{speedup}_{\\text{prefill}}\\approx\\frac{N+T}{k+T}$$</div>\n<p>当 T 很小（短问句、单图）时，ρ 接近 1，加速比接近 N/k，剪枝几乎线性兑现；当 T 已经上千（长文档、多轮历史），ρ 被稀释，即使 N/k 很大，端到端预填收益也被文本部分吃掉。这就是为什么同一套 k 配比在“单图短问”上表现亮眼，在“多图长上下文”上收益被摊薄——不是剪枝失效，是负载的视觉占比不够。工程上应把 ρ 作为路由特征：ρ 高的请求走激进 k，ρ 低的请求不必为剪枝付出打分器的那一点额外前向。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-21\">二十一 · 长度分布：固定 k 把分布压成一条线，也压掉了方差信息</h3>\n<p>固定预算 k 的直接后果是：无论输入图像是 4K 航拍还是 512×512 的商品图，进入 LLM 的视觉 token 数都一样。这让批内序列长度天然对齐——每条的视觉段长度恒为 k，调度器不必为变长视觉段做 padding 或分桶，连续批处理的 token 预算计算变得极其简单，批大小可以按 k+T 的上界直接估算。代价是长度分布的信息被抹平了：原本 N 的分布（简单图几百、复杂图上千）携带了“这张图有多难”的信号，固定 k 把它丢弃，于是同一批里简单图被过度保留、复杂图保留不足，批内精度方差变大。</p>\n<p>量化这个方差的工程含义：若批内各请求的真实信息需求 k* 服从某个分布，而系统统一用 k，则有效算力浪费为</p>\n<div class=\"formula\">$$\\text{waste}=\\frac{1}{B}\\sum_{b=1}^{B}\\max\\big(0,\\;k-k^{*}_{b}\\big),\\qquad \\text{deficit}=\\frac{1}{B}\\sum_{b=1}^{B}\\max\\big(0,\\;k^{*}_{b}-k\\big)$$</div>\n<p>waste 是白算的预填 FLOPs 与白占的 KV 显存，deficit 是精度损失。两者不可能同时为零，除非 k 随请求自适应。固定 k 的批调度优势（长度对齐、批大小可预测、SLO 好算）正是以这两项之一为代价换来的。一个可操作的折中是分层 k：按图像分辨率或视觉编码器输出的 N 分档，每档一个 k，档内仍然对齐，档间用不同的 token 预算，调度器按档分桶。这样既保留了对齐带来的批调度便利，又让 k 跟随 N 的粗粒度变化，把 deficit 压下去。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-22\">二十二 · 并发与批大小：k 缩小了单请求足迹，抬高了并发上限</h3>\n<p>KV cache 里视觉部分显存与 k 成正比，这是并发能力的直接杠杆。设每 token 每层 KV 字节数为 c、层数 L、批大小 B，则视觉 KV 显存为</p>\n<div class=\"formula\">$$M_{\\text{KV}}^{\\text{vis}}=B\\cdot k\\cdot L\\cdot c,\\qquad B_{\\max}\\approx\\frac{M_{\\text{budget}}-M_{\\text{weight}}-M_{\\text{textKV}}}{k\\cdot L\\cdot c}$$</div>\n<p>把 k 从 N 降到 N/4，视觉 KV 占用降为四分之一，在显存预算不变的前提下 B_max 大致抬到四倍（文本 KV 与权重占用不变时）。这对高并发在线服务是比单请求延迟更值钱的收益：吞吐由并发数乘单请求速度决定，而 k 同时改善两项——预填 FLOPs 随 k 下降，KV 带宽压力随 k 下降，并发上限随 k 上升。但要注意打分器本身是串在关键路径上的：它在视觉编码器之后、LLM 预填之前，是一个不可跳过的前向。当 B 很大时，打分器的算力开销会从“可忽略的轻量算子”变成“与视觉编码器前向同量级的固定成本”，尤其在小 k 区间，省下的 LLM 预填可能抵不过打分器的固定开销。判断阈值很直接：比较打分器单请求耗时与 (N−k) 个 token 的预填耗时，后者随 k 减小而增大，前者恒定，存在一个 k 的下界，再往下压就不划算了。</p>\n<p>批大小的另一个约束来自显存碎片：k 固定使视觉段长度恒定，KV 分页的块边界可预测，碎片率低；若改用自适应 k，视觉段变长，分页块跨请求复用的效率下降，调度器需要更细的块管理。这是固定 k 在系统层的隐性红利，也是自适应方案必须付出的调度复杂度。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-23\">二十三 · SLO 由 k 与文本长度共同决定，单一 SLO 覆盖不了全部流量</h3>\n<p>端到端延迟可拆为视觉编码器前向、打分器、LLM 预填（正比于 k+T）、解码（正比于输出长度且受 KV 带宽约束）。首 token 延迟 TTFT 主要由前三项决定，而其中只有第三项受 k 控制。于是 SLO 的可行域是二维的：k 与 T。对短问句，TTFT 对 k 敏感，降 k 立竿见影；对长文本请求，TTFT 被 T 主导，降 k 的边际收益迅速衰减。用一条 SLO 阈值去卡所有流量，结果是短问句请求被过度满足（k 可以更小却没降），长文本请求被误判为不达标（其实是 T 太长而非 k 太大）。正确做法是把 SLO 写成 (k, T) 的函数并按请求形态分池：视觉主导池用激进 k 卡 TTFT，文本主导池用保守 k 保精度，两池各自独立做批调度与容量规划。</p>\n<p>精度侧的 SLO 更难写。固定 k 下批内精度方差大，用平均精度做 SLO 会掩盖长尾失败：整图问答正常，局部识别系统性出错，而离线平均指标看不出来。工程判断是给细粒度任务单独设一条 k 下限，并在路由层按任务类型打标——这不是精度问题，是负载配方问题。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-24\">二十四 · 负载不对时的三种崩法</h3>\n<ul>\n<li><b>细粒度任务被系统性误删。</b>打分器与下游任务解耦，OCR 字符与小目标 patch 的特征范数或注意力分数偏低，top-k 直接删掉。表现为整图描述流畅、局部问答全错。修法是按任务上调 k 或换任务相关打分器，而非调阈值。</li>\n<li><b>复杂度失配导致的批内方差。</b>简单图过度保留浪费算力，复杂图保留不足丢精度，同一批里两种误差并存，平均指标掩盖长尾。修法是分层 k 或按 N 分桶。</li>\n<li><b>空间顺序被破坏。</b>top-k 后若未保持原始空间顺序，位置编码与视觉 token 序列错位，模型输出出现空间关系错误（左右颠倒、上下错位），且这类错误在离线指标上极难发现，因为语义分数可能仍然正常。修法是在选择后按原索引重排再送投影层。</li>\n</ul>\n<p>三种崩法有共同点：都不是数值精度或 kernel 问题，而是负载与配方的错配。它们不会在基准测试的均值上暴露，只会在特定流量切片上暴露。因此上线前必须按请求形态切片做回归，而不是只看总体平均。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-25\">二十五 · 配方落地：把 k 当成路由参数而不是常量</h3>\n<p>把上述约束收拢成一条工程规则：k 不应是全局常量，而应是路由层根据请求形态算出的参数，固定 k 只作为同一桶内的对齐手段。路由特征至少包含三项：视觉 token 数 N（分辨率与图数）、文本 token 数 T（决定 ρ）、任务类型标签（决定细粒度下限）。桶内用固定 k 换取批调度对齐与 KV 分页效率，桶间用不同 k 换取精度与算力的匹配。容量规划时按桶分别估算 B_max 与 TTFT，而不是用一个全局 k 推一个全局并发数。</p>\n<p>最后落在打分器与 k 的耦合上：打分器的归一化质量决定了同一 k 下保留 token 的信息密度，而 k 的大小决定了打分误差被放大的程度——k 越小，被删掉的 token 越多，打分器的一次误判代价越大。所以激进 k 必须配更稳的打分器（特征尺度归一化、避免范数主导），保守 k 才允许用最廉价的启发式。这条耦合关系是负载配方里最容易被忽略的一环：很多人只调 k 不调打分器，结果在低 k 区间精度断崖，误以为是剪枝本身不行，其实是打分误差在低 k 下被放大。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-26\">二十六 · 固定预算 k 的负载适配边界与失效形态</h3>\n<p>这套方案在负载配方上有一个隐含前提：请求的视觉信息密度大致均匀。固定预算 k 把批内每条样本的视觉序列长度对齐成同一个值，批调度因此变得极其干净——预填阶段的 token 数可预测，KV cache 的视觉部分按 k 而非 N 分配，显存占用与批大小呈线性可算。代价是 k 一旦写死，就同时承担了两个互相冲突的职责：既是吞吐旋钮，又是精度旋钮。高分辨率单图问答、多图对比问答这类形态与固定 k 契合，因为它们的复杂度分布集中；而混合流量——同一批里既有整页扫描件又有低分辨率示意图——会让固定 k 变成对简单图的过度保留和对复杂图的保留不足，批内序列长度虽然对齐，精度方差却拉大，单一 SLO 无法覆盖全部流量。</p>\n<p>失效的第一形态是打分器与下游任务解耦带来的系统性误删。轻量打分器用特征范数、注意力或多样性这类与任务无关的信号排序，细粒度 OCR 的小字区域、小目标检测的边缘 patch 往往特征响应弱，分数排在 top-k 之外被整块删除。整图问答仍然正常，局部识别任务却系统性失败，且这种失败不会在聚合指标上暴露。第二形态是空间顺序被破坏：top-k 选择后若未按原始 patch 顺序重排，位置编码与视觉 token 的实际空间关系错位，模型输出的空间指代出现错误，离线指标难以发现。第三形态是 k 的规模上限：k 过小则细粒度任务失效，k 过大则预填 FLOPs 与 KV 显存收益消失，收益曲线在两端都被压平。</p>\n<div class=\"formula\">$$\\text{keep}=\\text{TopK}\\big(s_i\\big)_{i=1}^{N},\\quad \\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>工程判断落在按任务类型分层配置 k，而不是全局单一预算。对 OCR 与小目标密集的请求上调 k，或改用任务相关打分器替换启发式打分；对示意图、图表类请求维持小 k。打分器需对特征尺度做归一化，避免范数主导选择。系统代价上，k 上调直接抬高预填算力与 KV 显存，硬件档位由视觉编码器前向与打分器决定，LLM 侧的带宽压力随 k 缩减而下降——这意味着负载配方本质是在视觉编码器侧多花算力、在 LLM 侧省显存与带宽的交换，交换比例由流量中细粒度任务占比决定。</p>\n<h3 id=\"alg-vprune-prelm-sec-27\">二十七 · 硬件档位：谁在决定下限</h3>\n<p>视觉剪枝把计算压力从 LLM 侧挪回视觉编码器侧，部署时必须先回答一个问题：这条流水线的瓶颈究竟落在哪一颗芯片上。打分器是轻量算子（特征范数、注意力权重或多样性度量），但它读的是视觉编码器输出的全部 N 个 patch token 特征，因此打分本身是一次对 N×d 特征矩阵的规约操作，带宽开销与 N 成正比，而真正的 top-k 选择只产出 k 个 token。在 Blackwell 档位上，这意味着视觉编码器前向与打分器共同决定了预填阶段的算力下限，而 LLM 侧因为只接收 k 个视觉 token，预填 FLOPs 与 KV 显存随之收缩。工程判断是：不要把剪枝当作“省 LLM 显存”的单一手段，它同时把负载重心推向前端编码器，若编码器本身已是高分辨率大模型，前端可能成为新的长尾。</p>\n<p>具体机制上，打分器对每个 token 计算 $s_i=f(\\mathbf{z}_i)$，其中 $\\mathbf{z}_i$ 是第 $i$ 个 patch token 的特征，$f$ 可取特征范数、注意力打分或多样性度量。若 $f$ 是范数，则是一次逐行 L2 归约，访存 $N\\cdot d$ 个元素、写回 $N$ 个标量；若 $f$ 依赖注意力，则需要一次额外的 token 间交互，代价从纯带宽转为带宽加算力。部署时应把打分器实现为融合 kernel，避免把 N×d 特征矩阵物化到 HBM 再读回——这一步在 N 达到数千、d 为数百时，单次前向的额外访存可达数十 MB 量级，直接反映为预填延迟的固定开销。</p>\n<p>一个具体例子：单张高分辨率图像产生数千个视觉 token，编码器输出后打分器在片上完成归约，仅将 k 个保留 token 经投影层送入 LLM。若把打分器写成两段式（先落盘特征再读回打分），预填延迟会被额外访存拉长；若写成融合式，前端代价主要落在编码器本身。硬件档位因此应表述为“编码器+打分器决定预填下限，LLM 侧因 k 缩减而降低显存与带宽压力”，而不是笼统地说“剪枝让推理变快”。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-28\">二十八 · 并行拓扑：k 对齐带来的批调度红利</h3>\n<p>固定预算 k 的一个直接工程后果是：同一批内所有请求的视觉 token 数相同，视觉段序列长度天然对齐。这与文本段长度参差不齐形成对比，使连续批处理在拼批时可以把视觉段视为定长前缀，减少 padding 与变长 kernel 的分支。并行拓扑上，视觉编码器通常按图像切分做数据并行，打分与 top-k 是逐 token 独立的规约，天然可并行；LLM 侧则按张量并行或专家并行切分，视觉 token 作为前缀参与注意力计算。关键约束是 top-k 之后必须保持空间顺序，否则位置编码与视觉 token 顺序错位，模型输出出现空间关系错误且不易通过离线指标发现。</p>\n<p>伪代码思路可写成：编码器输出 $\\{\\mathbf{z}_i\\}_{i=1}^{N}$；打分得到 $\\{s_i\\}$；对分数做尺度归一化后取 $S=\\mathrm{TopK}(\\{s_i\\},k)$；按原始索引排序保留 token；投影后拼接文本 token 进入预填。排序这一步在并行实现中是收集-重排，代价是 k 个 token 的索引 scatter，量级远小于 N 个 token 的打分归约，但若省略排序，位置编码错位带来的精度损失无法用吞吐收益抵消。</p>\n<p>代价方面，视觉段定长使批调度器可以用单一序列长度上界估算显存，KV cache 按 k 个视觉 token 分配，$M_{\\text{KV}}^{\\text{vis}}/M_{\\text{KV}}^{\\text{full}}=k/N$。举例：N 为数千、k 取数百时，视觉 KV 占比降到十分之一量级，批内可容纳的请求数随之上升；但若不同请求的图像复杂度差异大，固定 k 会让简单图过度保留、复杂图保留不足，批内精度方差大，难以用单一 SLO 覆盖全部流量。并行拓扑的选择因此要配合按任务类型分流的队列，而不是把所有流量塞进同一固定 k。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-29\">二十九 · 量化方案：与语言模型精度对齐</h3>\n<p>剪枝发生在预填之前，量化则发生在权重与激活上，两者在部署配方中必须对齐精度口径。视觉编码器与打分器是轻量前端，量化收益有限但风险明确：打分器依赖特征尺度，若对特征做低比特量化，范数打分会被量化噪声主导，选择结果偏离。因此打分器应保持较高精度或至少对特征做归一化后再量化，避免范数主导选择。LLM 侧的量化可与语言模型精度对齐，视觉 token 作为前缀进入同一套权重与激活量化路径，不需要为视觉段单独设计一套数值格式。</p>\n<p>公式层面，剪枝带来的收益是 token 数从 N 降到 k，量化带来的收益是每 token 的字节数下降，两者相乘才是端到端显存与带宽的缩减。KV cache 按 k 个视觉 token 分配后，若再对 KV 做低比特存储，视觉段显存进一步压缩；但视觉 token 的空间顺序与位置编码一致性要求 KV 的索引顺序不能因量化打包而错乱。工程判断是：先固定 k 与空间顺序，再在 LLM 侧套用与文本一致的量化方案，前端打分器保持归一化后的高精度，避免把两个正交的压缩手段耦合进同一次数值近似。</p>\n<p>具体例子：高分辨率多图问答请求，视觉段经剪枝后 k 个 token 进入 LLM，KV 按 k 分配；若语言模型侧采用低比特权重与激活，视觉前缀与文本共享同一量化路径，无需额外校准集。代价是量化误差与剪枝误差叠加，细粒度 OCR 与小目标本就被打分器误删，再叠加低比特激活会放大失败率，因此这类任务应上调 k 或改用任务相关打分，而不是靠提高量化比特数补救。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-30\">三十 · KV 策略：按 k 分配与预算的耦合</h3>\n<p>KV 策略的核心是把显存预算从 N 改为 k。视觉 token 的 KV 在预填时一次性写入，解码阶段只读，因此按 k 分配意味着预填阶段的写入带宽与解码阶段的读取带宽同步下降。$\\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$ 是这条策略的唯一杠杆：k 越小，视觉 KV 越省，但打分器与下游任务解耦导致的误删风险越高。部署配方应把 k 作为显式配置项暴露给调度器，而不是藏在模型内部常量里。</p>\n<p>机制上，保留 token 经投影层进入 LLM 预填，KV cache 仅按 k 个视觉 token 分配，剪枝完全发生在预填之前。这意味着 KV 的分配发生在知道 k 之后，批调度器可以用 k 加文本长度估算每条请求的显存占用，从而做准入控制。代价是固定预算对图像复杂度不敏感：简单图过度保留浪费显存，复杂图保留不足损失精度。一个可复现的做法是按任务类型设多档 k，OCR 与小目标检测走大 k 档，整图问答走小 k 档，调度器按队列标签选择档位，使 SLO 由 k 与文本长度共同决定而不是单一常数。</p>\n<p>具体例子：同一批内混合整图问答与局部识别请求，若统一用一个小 k，局部识别请求系统性失败；若统一用大 k，整图问答的显存收益消失。分档后，批内序列长度仍可按档对齐，KV 预算按档估算，精度方差被队列隔离而不是被平均掉。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-31\">三十一 · 调度参数：可复现的配置思路</h3>\n<p>把上述四件事收拢成一份可复现配置，需要固定五个参数：k 的档位表、打分器类型与归一化方式、空间顺序保持开关、量化口径、以及按任务标签分流的队列策略。打分器选择上，特征范数最轻但最易被尺度主导，注意力打分更贴近任务但需要额外交互，多样性打分介于两者之间；无论哪种，都必须对特征尺度做归一化，避免范数主导选择。空间顺序保持是硬开关，不可关闭。</p>\n<p>调度参数上，批大小可按固定 k 对齐序列长度从而便于批调度，准入控制用 k 加文本长度估算显存；SLO 由 k 与文本长度共同决定，图像越复杂越需要更大 k。失败模式有三类需要写进配置检查清单：细粒度 OCR 或小目标 token 分数偏低被 top-k 删除，整图问答正常但局部识别系统性失败；固定预算对简单图过度保留、对复杂图保留不足，批内精度方差大；top-k 后未保持空间顺序，位置编码错位且离线指标难以发现。</p>\n<p>一个可复现的配置思路是：先按任务标签把流量分成“整图理解”与“细粒度识别”两条队列，前者用小 k 档、后者用大 k 档；打分器统一用归一化后的特征范数做基线，细粒度队列可换注意力打分；LLM 侧量化与文本对齐，打分器保持高精度；KV 按档位 k 分配并在准入时估算；批调度按档内定长对齐。规模上限由打分器与任务的相关性决定，k 过小则细粒度任务失效，k 过大则收益消失，因此档位表要随流量构成定期复核，而不是一次设定后固化。</p>\n<p>工程判断落在最后一步：这套配方的收益上界由 $k/N$ 决定，但精度下界由打分器与任务的相关性决定，两者不在同一坐标系里。部署时应把 k 当作 SLO 参数而非性能旋钮，先定精度可接受的 k 下界，再在该下界之上做显存与吞吐的权衡；任何试图用单一固定 k 覆盖全部流量的配置，都会在细粒度任务上暴露系统性失败，而这种失败不会出现在整图问答的离线指标里。</p>\n\n\n<h3 id=\"alg-vprune-prelm-sec-32\">三十二 · 固定 k 的部署边界：打分器失配、批对齐假象与显存账</h3>\n<p>这套配方能落地的前提，是把 k 当作一个**部署期常量**而非自适应量。批调度之所以简单，是因为保留 token 经投影层后序列长度恒为 k 加文本长度，连续批处理里不会出现视觉段长度抖动，调度器无需为每条请求单独估算预填规模。代价随之而来：<span class=\"formula\">$$\\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</span> 这个比值是显存账的全部依据，k 一旦定死，KV 预算就与图像内容脱钩。高分辨率多图问答里 N 可达数千，k 取小则单请求 KV 显存与预填 FLOPs 同步压缩，但压缩比是均匀施加的——简单图（大面积纯色背景、单主体）被过度保留，复杂图（密集表格、小字标注）保留不足，批内序列长度虽已对齐，精度方差却落在任务维度上，单一 SLO 无法同时覆盖两类流量。</p>\n<p>失效条件集中在打分器与下游任务的解耦上。打分器 f 取特征范数、注意力或多样性，对细粒度 OCR 与小目标天然不利：小字 patch 的特征响应弱于大块语义区域，top-k 直接把它们删掉，整图问答指标正常而局部识别系统性失败，且这种失败不会在常规离线评测中暴露。工程上的处置不是调 f，而是按任务类型分档：OCR 与小目标检测走更大的 k 或换任务相关打分，通用问答走默认 k。打分器还必须对特征尺度做归一化，否则范数项会主导选择，注意力与多样性打分形同虚设。top-k 之后保持空间顺序是硬约束——顺序错位会破坏位置编码一致性，输出出现空间关系错误，且这类错误在聚合指标上几乎不可见。</p>\n<p>硬件档位的划分点不在 LLM 侧。视觉编码器前向与打分器是固定成本，与 k 无关；LLM 侧的显存与带宽压力随 k 线性下降，因此档位选择实际是“编码器算力 vs 解码器显存”的权衡。量化与语言模型精度对齐即可，KV cache 只按 k 个视觉 token 分配，视觉段的量化误差不会因剪枝而放大。规模上限由打分器与任务的相关性决定：k 过小则细粒度任务失效，k 过大则预填收益消失，固定预算对图像复杂度不敏感是扩展的主要瓶颈。可复现的配置思路是：先按最复杂流量的精度下限反推 k，再用简单图流量验证过度保留带来的显存浪费是否可接受，最后把 k 写进调度参数而非模型参数。</p>\n<h3 id=\"alg-vprune-prelm-sec-33\">三十三 · 预填侧的系统账：k 决定了什么在崩</h3>\n<p>把视觉 token 从 N 压到 k 之后，系统账本上最先变化的不是解码阶段，而是预填阶段。视觉 token 在进入 LLM 之前就已经被截断，因此 LLM 预填的序列长度从 N+T 变为 k+T（T 为文本 token 数），预填 FLOPs 随序列长度近似线性增长的那一部分被直接削掉。更关键的是 KV cache：视觉位置的 KV 只按 k 个 token 分配，显存占用比例为</p>\n<div class=\"formula\">$$\\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>这个比例是整条链路上最干净的收益项，因为它与批大小、与文本长度都无关，只由保留预算决定。以高分辨率图像数千个 patch token 为例，若 k 取到 N 的四分之一，视觉 KV 显存即降到四分之一；在 NVL72 这类以显存容量换取并发度的平台上，这意味着同一张 GPU 上可以塞进更多并发请求，或者把省下的显存留给更长的文本上下文与更大的批。代价出现在打分器一侧：打分器必须在视觉编码器输出后、投影层之前完成一次全量 N token 的遍历，这一步的算力与带宽开销与 N 成正比，且不受 k 影响。当 N 很大而 k 很小时，打分器本身会成为预填路径上的固定成本，收益的边际递减从这里开始。</p>\n<p>具体机制上，打分器读的是编码器输出的 patch 特征张量，做一次逐 token 的范数或注意力打分，再执行 top-k。这是一次性、无迭代的选择，没有重构基、没有误差回传，因此它的显存峰值只取决于 N×d 的特征张量本身，而不取决于 k。工程判断是：当 N 达到数千量级、d 为编码器隐藏维时，这个特征张量在批内会随批大小线性叠加，打分器的临时显存可能反过来成为预填阶段的峰值占用者。此时把打分与选择做成融合算子、按块流式处理特征、避免物化完整的分数向量，比继续压低 k 更能改善显存曲线。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-34\">三十四 · 带宽与通信：省下的是 KV 流量，不是权重流量</h3>\n<p>视觉剪枝改变的是激活与 KV 的流量结构，不改变模型权重的流量结构。解码阶段每个 step 都要把 LLM 权重从 HBM 读一遍，这部分带宽开销与 k 无关；被削减的是视觉位置的 KV 读写，以及预填阶段因序列变短而减少的激活搬运。因此在带宽受限的 decode 场景里，视觉剪枝的收益是局部的：它让每个请求的 KV 工作集变小，从而在同样的 HBM 带宽下支撑更高的并发，但单请求的每 step 权重带宽不变。把这一点换算成吞吐，收益来自并发度而非单请求延迟。</p>\n<p>通信侧的情况更微妙。在张量并行或分离式预填/解码部署中，预填节点要把 KV 传给解码节点，传输量与序列长度成正比。视觉 KV 从 N 降到 k，直接压缩了这条链路上的字节数，对 NIXL 这类以 KV 传输为核心的连接层是实打实的减负。但打分与 top-k 发生在预填节点的视觉编码器之后，属于本地计算，不引入额外集合通信；真正需要注意的是批内序列长度对齐——固定 k 让每个请求的视觉段长度一致，预填批的形状因此变得规整，这对 NCCL 集合通信的负载均衡是有利的，避免了因图像分辨率不同导致的批内长度方差。反过来，如果为了照顾复杂图像而按请求动态调整 k，批内长度重新变得不齐，通信与计算的负载均衡会退化，这是固定预算在系统层面的隐性价值。</p>\n<p>一个具体例子：多图问答请求在一个批里混合了简单图标图与密集文档图。固定 k 下两者视觉段等长，预填批是一次规整的矩阵乘，KV 传输量可预测；若改成按复杂度分配 k，批内出现长短不一的视觉段，预填需要 padding 或分桶，padding 部分白算，分桶则增加调度开销。系统代价体现在预填利用率上：padding 比例越高，省下的 KV 显存越容易被浪费的预填算力抵消。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-35\">三十五 · 功耗与规模上限：谁先撞墙</h3>\n<p>规模上去以后，第一个撞墙的通常不是算力，而是显存容量与打分器的固定开销之间的夹击。k 越小，KV 显存越省，但打分器仍要遍历全部 N 个 token，这部分功耗与时间不随 k 缩小。当 k 压到很小、批开得很大时，系统进入一个区间：KV 显存已不再是瓶颈，打分器与视觉编码器前向成为预填阶段的主导成本，继续减小 k 带来的吞吐增益趋近于零，而细粒度任务的精度损失却在累积。这就是该算法规模扩展的主要瓶颈——固定预算对图像复杂度不敏感，使得系统无法通过统一调参同时满足简单图与复杂图。</p>\n<p>功耗角度，视觉编码器前向与打分器是预填阶段的功耗大头，LLM 预填因序列缩短而功耗下降，解码阶段因并发上升而总功耗上升。整体功耗曲线不是单调下降的：剪枝把功耗从 LLM 侧转移到视觉侧，再把解码侧的总功耗通过更高并发推上去。容量规划时要按“视觉前向 + 打分”的固定功耗加上“解码并发 × 每 step 权重带宽功耗”来估算，而不是简单按 k/N 折算。第二个撞墙点是尾延迟：固定 k 让批内序列等长，理论上尾延迟应更可控，但打分器对 N 的依赖意味着高分辨率请求的预填时间仍由 N 决定，一张超大图的打分阶段可能成为该批的拖尾项，批内其他请求被迫等待。</p>\n<p>具体机制上，尾延迟的来源可以定位到打分器的串行遍历：它对 N 个 token 逐个或分块打分，N 越大这一段越长，且无法通过减小 k 缩短。缓解手段是把打分与视觉编码器的最后一层融合，让打分在读特征的同时完成，避免二次遍历；或者在调度层按 N 分桶，把超大图请求单独成批，避免它拖住一批小图请求。系统代价是分桶带来的批利用率下降，需要与尾延迟 SLO 权衡。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-36\">三十六 · 失败模式在系统指标上的投影</h3>\n<p>打分器与下游任务解耦的失败模式，在系统指标上表现为精度方差而非均值下降。整图问答类流量指标正常，但细粒度 OCR 与小目标识别请求出现系统性失败：这些任务的 token 分数偏低，被 top-k 删除，模型输出在局部区域出错。系统层面这不会表现为吞吐或延迟异常，只会表现为特定流量切片的准确率塌陷，因此离线聚合指标难以发现，必须按任务类型切片监控。工程上的应对是按任务类型上调 k 或改用任务相关打分，代价是这些切片的 KV 显存与预填算力回到较高水平，容量规划需要为混合流量预留两套预算。</p>\n<p>第二个失败模式是固定预算导致的批内精度方差：简单图过度保留、复杂图保留不足，批内序列长度虽对齐，但各请求的有效信息密度差异很大，单一 SLO 无法覆盖全部流量。系统上这表现为同一批内不同请求的端到端延迟相近而质量差异显著，调度器无法用延迟指标区分好坏请求。第三个失败模式是 top-k 后未保持空间顺序，位置编码与视觉 token 顺序错位，输出出现空间关系错误；这类错误在离线指标上不易暴露，却会在涉及方位、布局的请求上稳定复现。保持空间顺序是一个几乎零成本的约束，但一旦在实现中为了紧凑内存布局而打乱顺序，排查成本极高，因为它不改变任何吞吐或延迟指标。</p>\n<p>把三类失败模式放在一张系统表里看，它们的共同点是：都不体现在主指标上，都要求按流量切片做质量监控。这与该算法“训练-free、打分器与任务解耦”的定位直接相关——没有任务相关信号，就没有任务相关的系统反馈，只能靠外部切片监控补上这一环。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-37\">三十七 · 容量规划中的 k 与批的耦合</h3>\n<p>容量规划的核心是把 k 从算法参数翻译成资源参数。给定目标并发 C、文本长度 T、每 token KV 字节数 b，视觉 KV 显存约为 C·k·b，预填算力约为 C·(k+T) 的线性项加上打分器的 C·N 固定项。两个式子联立可以看出：k 的下降对显存是线性收益，对预填算力则被打分器的 N 项稀释。因此在小 k 区间，继续压 k 换显存的性价比下降，而把批开大换吞吐的性价比上升；在大 k 区间则相反。规划时应先确定打分器与视觉前向的固定成本占比，再决定 k 的取值区间，而不是把 k 当作独立的调参旋钮。</p>\n<p>另一个耦合点是量化。KV cache 按 k 个视觉 token 分配后，若语言模型侧采用低精度 KV，视觉 KV 的字节数 b 同步下降，k 与 b 的乘积共同决定显存。量化与剪枝在这里是乘性关系而非加性关系：两者都作用在同一个 k·b 上，因此同时启用时显存收益叠加，但精度损失也叠加，且损失来源不同——剪枝丢的是 token，量化丢的是数值分辨率。容量规划需要为两者分别留出精度预算，不能把省下的显存全部兑换成并发。</p>\n<p>具体例子：一个以文档理解为主的服务，N 为数千、T 中等、并发目标较高。若按固定 k 规划，简单图请求会过度保留，浪费的显存本可用于提高并发；若按复杂度动态调 k，批内长度失齐，预填利用率下降。可行的折中是按流量分层：把简单图路由到小 k 的批、复杂图路由到较大 k 的批，两层各自保持批内等长，用调度层的分桶换取两套 SLO。代价是调度复杂度与批利用率，收益是每一层都能把 k 压到该层真正需要的水平，避免全局固定预算的系统性浪费。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-38\">三十八 · k 一旦固定，系统瓶颈就从算力转到调度与尾延迟</h3>\n<p>把视觉 token 从 N 削到 k 之后，预填 FLOPs 与 KV 显存都按比例收缩，<span class=\"formula\">$$\\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</span> 这条比值直接决定了单请求的显存占用上限。但真正的工程分水岭在于：当 k 固定、批大小按 k 对齐序列长度时，批内每条请求的视觉 token 数相同，调度器可以把视觉段当成定长块来切分，连续批处理的填充浪费被压到很低；代价是图像复杂度不再进入调度决策。简单图（大面积纯色、少文字）在 k 下被过度保留，多出来的 token 白白占用预填算力与 KV 带宽；复杂图（密集小字、多目标）则保留不足，精度塌陷却不会在批级吞吐指标上留下任何痕迹。规模上去以后，最先崩的不是单卡算力，而是批内精度方差——同一 SLO 覆盖不了混合流量。</p>\n<p>带宽侧的账要分开算。视觉编码器前向与打分器是固定开销，与 k 无关；一旦 k 缩到很小，这部分开销在端到端延迟中的占比反而上升，出现“剪得越狠、编码器越显眼”的反转点。KV cache 的读带宽随 k 线性下降，解码阶段的每 token 显存访问量随之降低，这是剪枝最实在的收益；但打分器本身要读一遍全部 N 个 token 特征做范数或注意力打分，这次全量读发生在预填之前，属于不可摊销的额外带宽。当 N 达数千、批内请求数上升时，打分器的全量读会与编码器前向争抢同一段 HBM 带宽，成为预填阶段的隐性瓶颈。</p>\n<p>通信与尾延迟在分离式部署下暴露得更彻底。预填节点做完 top-k 后只把 k 个 token 的激活与位置信息传给解码节点，传输量按 k/N 缩减，NIXL 上的 KV 搬运压力同步下降；但 top-k 选择必须保持空间顺序，否则位置编码与视觉 token 顺序错位，输出出现空间关系错误且离线指标难以发现——这是一条必须在打分器输出端做稳定排序的硬约束。尾延迟的来源则是打分器与下游任务解耦：细粒度 OCR 或小目标 token 分数偏低被删除，整图问答正常、局部识别系统性失败，这类请求在 P99 上表现为“看似成功但答案错”，无法靠超时或重试兜底。</p>\n<table class=\"mini\"><thead><tr><th>规模变量</th><th>先崩的位置</th><th>工程对策</th></tr></thead><tbody><tr><td>批大小上升</td><td>打分器全量读争抢 HBM 带宽</td><td>打分与编码器前向分核、按请求形态分批</td></tr><tr><td>k 压得过小</td><td>细粒度任务精度方差</td><td>按任务类型上调 k 或换任务相关打分</td></tr><tr><td>混合流量</td><td>单一 SLO 无法覆盖</td><td>按图像复杂度分档路由，而非全局固定 k</td></tr></tbody></table>\n<p>因此规模扩展的上限不在 LLM 侧，而在打分器与任务的相关性：k 过小则细粒度任务失效，k 过大则预填与显存收益消失，固定预算对图像复杂度不敏感是这套方案最主要的扩展瓶颈。工程判断是——把 k 从全局常量改成按请求形态分档的调度参数，让简单图走小 k、复杂图走大 k，批内序列长度不再严格对齐但换来精度方差收敛；若必须保持定长批，则至少为 OCR/小目标流量单开一条高 k 通道，用显存换尾延迟的可预测性。</p>\n<h3 id=\"alg-vprune-prelm-sec-39\">三十九 · 精度塌陷的三种签名与定位手段</h3>\n<p>在预语言模型视觉剪枝这条路径上，精度问题几乎不会以“整体掉点”的形式出现，而是以三种可区分的签名暴露出来。第一种是<strong>局部塌陷</strong>：整图问答、场景描述、计数类问题保持稳定，但 OCR、票据字段、小目标定位系统性失败。其成因是打分器与下游任务解耦——特征范数或注意力打分对小尺寸、低对比度 patch 天然给低分，top-k 直接把承载文字笔画的 token 删掉，LLM 侧再强的能力也无法从缺失的视觉证据里恢复。第二种是<strong>空间错位</strong>：top-k 之后若按分数排序而非按原始 patch 索引重排，位置编码与视觉 token 的真实空间关系脱钩，模型输出出现左右颠倒、上下错置、指代漂移，这类错误在聚合指标上几乎不可见，只有逐样本的空间关系探针才能捕获。第三种是<strong>预算失配</strong>：固定 k 对简单图过度保留、对复杂图保留不足，导致同一批次内精度方差极大，均值指标看似正常而分位数尾部已经崩坏。</p>\n<p>诊断这三类问题不能依赖单一端到端分数，而要构造分层探针。工程上可行的做法是在离线评测集上按任务类型切片，对每个切片单独统计保留率与命中率，并引入一个<em>证据留存率</em>指标：对标注了关键区域的样本，计算关键区域 patch 中被保留的比例。该指标与端到端精度的相关性远高于整体 token 保留率。公式上可写成</p>\n<div class=\"formula\">$$\\rho_{\\text{evid}}=\\frac{1}{|\\mathcal{R}|}\\sum_{r\\in\\mathcal{R}}\\frac{|S\\cap r|}{|r|},\\quad S=\\mathrm{TopK}\\big(\\{s_i\\}_{i=1}^{N},k\\big)$$</div>\n<p>其中 $\\mathcal{R}$ 是关键区域 patch 集合，$S$ 为保留集合。当 $\\rho_{\\text{evid}}$ 在 OCR 切片上明显低于场景切片时，基本可以判定为打分器解耦导致的误删，而非 LLM 侧的问题。代价方面，这套探针本身要跑一遍视觉编码器与打分器，单样本额外开销约等于一次预填的视觉前向，属于可接受的离线诊断成本；但若把它放进在线链路做逐请求监控，就会把预填 FLOPs 从 $k$ 量级重新推回 $N$ 量级，收益直接归零，因此必须限定在采样流量或影子链路上。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-40\">四十 · OOM 的真实来源：不是 k，而是批内长度方差</h3>\n<p>直觉上剪枝后 KV cache 按 $k$ 个视觉 token 分配，显存应当线性下降，OOM 不该发生。实际部署中 OOM 往往来自三个被忽视的角落。其一是<strong>多图请求</strong>：单图预算 k 固定，但一个请求携带多张高分辨率图时，视觉 token 总量是 $m\\cdot k$，$m$ 为图数，批调度若按单图预算估算显存就会低估。其二是<strong>文本侧长尾</strong>：视觉 token 被压缩后，文本 prompt 与生成长度占比上升，KV cache 的文本部分不再被视觉部分掩盖，长上下文请求的显存峰值由文本主导。其三是<strong>批内长度不均</strong>：固定 k 让视觉段长度对齐，但文本段长度仍随请求波动，连续批处理在拼接时按最长序列分配激活与临时缓冲，短请求被长请求拖累，显存利用率下降而峰值上升。</p>\n<p>显存核算应写成按请求求和而非按批求平均：</p>\n<div class=\"formula\">$$M_{\\text{batch}}=\\sum_{j=1}^{B}\\Big(m_j\\cdot k\\cdot d_{\\text{kv}}+L_j^{\\text{txt}}\\cdot d_{\\text{kv}}\\Big)+M_{\\text{act}}(L_{\\max})$$</div>\n<p>其中 $d_{\\text{kv}}$ 为每 token 的 KV 字节数，$L_j^{\\text{txt}}$ 为文本长度，$M_{\\text{act}}$ 由批内最长序列决定。工程判断是：把视觉预算 k 与文本长度上限一起纳入准入控制，对 $m_j\\cdot k+L_j^{\\text{txt}}$ 超过阈值的请求做拒绝或降级（降 k 或降分辨率），而不是等 OOM 触发后依赖重试。监控上应采集批内 $m_j\\cdot k$ 的分布而非均值，尾部分位数才是 OOM 的先兆。代价是准入控制会牺牲一部分吞吐，但在显存受限的分离式部署中，一次 OOM 导致的重调度与缓存清空代价远高于拒绝几个长请求。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-41\">四十一 · 批抖动与路由不均：固定 k 掩盖不了的调度病</h3>\n<p>固定 k 的一个副作用是让视觉段长度整齐，调度器误以为批已经同质，从而放松了对文本段的长度分桶。结果是<strong>批抖动</strong>：相邻批的预填耗时方差变大，因为视觉段省下的时间被文本段的长尾吃掉，迭代间隔忽长忽短，连续批处理的填充率下降。更隐蔽的是<strong>路由不均</strong>：在多副本或分离式预填/解码架构中，若按请求数而非按 token 数做负载均衡，携带多图或长文本的请求会集中打到少数副本，这些副本的显存与带宽先饱和，而其他副本空转。剪枝降低了单请求的平均 token 数，反而让按请求数均衡的偏差更严重，因为请求间的 token 差异被压缩到文本侧后相对权重更大。</p>\n<p>可操作的监控口径是按 token 计的路由权重与副本级队列深度。伪代码思路是：</p>\n<ul>\n<li>对每个请求计算权重 $w_j=m_j\\cdot k+L_j^{\\text{txt}}$，路由时按 $w_j$ 累加而非按 1 累加；</li>\n<li>副本选择用加权最少连接，队列深度以 token 为单位而非请求数；</li>\n<li>采集每个副本的 $w$ 分布与预填耗时分位数，偏差超过阈值即触发再均衡。</li>\n</ul>\n<p>代价在于加权路由需要请求在进入调度前就完成图像解码与 token 计数，把一部分本可流水线化的开销前移；对高分辨率多图请求，这一步的 CPU 与显存占用不可忽略。工程上通常用一个轻量的元数据探测（分辨率与图数）估算 $w_j$，精度足够做路由决策而不必真正跑完视觉编码器。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-42\">四十二 · 尾延迟尖刺：打分器与视觉前向的耦合点</h3>\n<p>剪枝把 LLM 侧的预填 FLOPs 压到 $k$ 量级，但视觉编码器与打分器的前向仍按 $N$ 量级执行，这部分开销在总延迟中的占比随 k 减小而上升。尾延迟尖刺通常来自三个耦合点。第一，<strong>打分器与编码器的串行依赖</strong>：打分必须在编码器输出后执行，无法与编码器并行，高分辨率图的编码器前向本身就有长尾，打分再叠加一次规约，尖刺被放大。第二，<strong>top-k 的规约开销</strong>：$N$ 可达数千，top-k 在 GPU 上是分段规约加排序，k 较小时仍需扫描全部 $N$ 个分数，其耗时与 $N$ 成正比而与 $k$ 无关，成为固定成本。第三，<strong>多图请求的串行编码</strong>：$m$ 张图若串行过编码器，延迟随 $m$ 线性增长，而 LLM 侧因 k 固定几乎不变，端到端延迟由视觉侧主导。</p>\n<p>诊断尾延迟要把链路切成编码、打分、top-k、投影、预填、解码六段分别计时，观察尖刺落在哪一段。若尖刺集中在打分与 top-k，说明固定成本在 $N$ 上，应考虑把打分器与编码器的最后一层融合、或对超大分辨率图做前置降采样；若尖刺集中在编码段且随 $m$ 增长，则应对多图做并行编码并限制单请求图数。系统代价上，视觉侧前向是这条路径的延迟下限，k 再小也无法突破；因此在 SLO 由尾延迟定义的场景里，视觉编码器的批处理与图数上限比 k 的调优更能压住尖刺。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-43\">四十三 · 监控指标体系与回滚判据</h3>\n<p>监控要覆盖四个层面，且每个层面都要有可执行的判据而非仅展示曲线。精度层：分任务切片的证据留存率 $\\rho_{\\text{evid}}$ 与端到端精度的联合监控，当 OCR 切片的 $\\rho_{\\text{evid}}$ 跌破基线即判定为打分器误删。显存层：批内 $m_j\\cdot k$ 的尾部分位数与文本 KV 占比，尾部越限即触发准入降级。调度层：副本级 token 加权队列深度与预填耗时分位数，偏差持续存在即触发再均衡。延迟层：六段分解计时的尾部分位数，定位尖刺段落。</p>\n<p>回滚判据应当是分级的，而不是一刀切关闭剪枝。第一级是<strong>预算回滚</strong>：把 k 按任务类型上调，OCR 与小目标流量走更大的 k，简单图流量维持小 k，这保留了大部分吞吐收益。第二级是<strong>打分器回滚</strong>：从解耦的启发式打分切换到任务相关打分或保留空间顺序的多样性打分，代价是需要额外的打分逻辑但仍在预填之前完成。第三级是<strong>路径回滚</strong>：对特定请求类型完全绕过剪枝，把全部 $N$ 个 token 送入 LLM，KV 显存回到 $N$ 量级，仅作为兜底。回滚的触发应当是自动的，依据是分片精度指标与尾延迟指标的联合越限，而非人工巡检；同时回滚状态要带时间窗与流量标签，避免一次异常样本导致全局降级。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>首选动作</th><th>系统代价</th></tr></thead><tbody><tr><td>细粒度误删</td><td>OCR 切片 $\\rho_{\\text{evid}}$ 下降</td><td>按任务上调 k</td><td>预填 FLOPs 与 KV 随 k 回升</td></tr><tr><td>空间错位</td><td>空间关系探针失败</td><td>恢复原始索引重排</td><td>无额外算力，仅规约顺序调整</td></tr><tr><td>OOM</td><td>批内 $m_j\\cdot k$ 尾部越限</td><td>准入降级或降分辨率</td><td>拒绝长请求，吞吐略降</td></tr><tr><td>路由不均</td><td>副本 token 队列深度偏差</td><td>加权最少连接</td><td>调度前移元数据探测开销</td></tr><tr><td>尾延迟尖刺</td><td>打分/top-k 段尾部分位数</td><td>融合打分或前置降采样</td><td>视觉侧固定成本仍在 $N$ 上</td></tr></tbody></table>\n<p>这张表的关键在于每一行都对应一个可在预填之前或之中执行的开关，而不是事后分析。剪枝发生在 LLM 之前这一结构决定了所有补救动作都不需要触碰解码器，回滚的粒度可以细到单个请求类型，这是这条路径在工程上相对于层内压缩的一个实际优势。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-44\">四十四 · 把诊断嵌进数据流：一个可落地的判断</h3>\n<p>最终要回答的是诊断逻辑放在哪里。把探针与判据嵌在打分器之后、投影层之前是最经济的做法：此处已经拿到全部 $N$ 个分数与保留集合 $S$，计算 $\\rho_{\\text{evid}}$ 只需对采样请求做一次集合交集，开销远小于重跑编码器；同时可以在同一位置执行预算回滚，把 k 动态上调后重新 top-k，而无需回退到更上游。工程判断是：<strong>剪枝路径的稳定性不取决于 k 选得多好，而取决于误删能否在进入 LLM 之前被识别并局部修正</strong>。固定预算对图像复杂度不敏感是这条路径的规模瓶颈，而把诊断嵌进打分与投影之间，等于用一次廉价的集合运算换取了按请求自适应 k 的能力，代价是打分器需要输出分数分布而不只是 top-k 索引，以及调度器需要接受变长视觉段——后者会重新引入批内长度方差，需要用第一节的显存核算口径兜住。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-45\">四十五 · 边界与失效：打分器解耦带来的三类系统性故障</h3>\n<p>这套方案的全部收益都押在一个假设上：轻量打分器给出的 <span class=\"inline-math\">s_i=f(z_i)</span> 与下游任务真正需要保留的 token 高度相关。一旦这个假设在流量分布上破裂，故障不是随机的性能抖动，而是<strong>系统性、可复现的精度塌陷</strong>。最典型的是细粒度 OCR 与小目标：字符笔画、远处路牌这类 patch 的特征范数往往不突出，注意力打分也因缺少任务上下文而偏低，于是被 top-k 干净地删掉。整图问答仍然正常，因为语义主干还在；但局部识别任务会稳定失败，且离线整图指标几乎察觉不到。诊断手段是把评测按任务类型切片，单独统计 OCR、计数、小目标定位的子集准确率，并对被删 token 的空间分布做直方图——若删除集中在图像边缘或高纹理区，基本可判定为打分器与任务解耦所致。处置不是调阈值，而是按任务类型上调 <span class=\"inline-math\">k</span>，或换成任务相关打分器。</p>\n<p>第二类故障来自固定预算对图像复杂度的不敏感。简单图被过度保留，浪费预填算力；复杂图保留不足，精度方差在批内被放大。批内序列长度虽因固定 <span class=\"inline-math\">k</span> 而对齐、批调度顺畅，但精度方差大意味着单一 SLO 无法覆盖全部流量：同一批里既有轻松达标的请求，也有静默降质的请求。监控上应把 <span class=\"inline-math\">k/N</span> 与图像复杂度代理量（patch 数、边缘密度）联合打点，观察精度与 <span class=\"inline-math\">k</span> 的回归斜率；斜率显著为正即说明预算偏紧。代价是显存与带宽随 <span class=\"inline-math\">k</span> 线性增长，<span class=\"inline-math\">k</span> 上调直接吃掉收益，因此这是一个必须显式定价的权衡，而非免费的安全边际。</p>\n<p>第三类是空间顺序错位。top-k 之后若未按原始 patch 索引重排，位置编码与视觉 token 顺序错位，模型输出的空间关系（左右、上下、相对位置）会出现难以归因的错误，且这类错误在聚合指标上被稀释，不易通过离线评测发现。工程上应把“保序”写成选择算子的后置不变量并在 CI 中断言，而非依赖实现自觉。回滚策略对应三层：打分器版本与 <span class=\"inline-math\">k</span> 作为可热切换配置下发，精度切片告警触发按任务路由回退到全量 token 路径；KV 显存按 <span class=\"inline-math\">k</span> 预分配，回退时需预留全量 <span class=\"inline-math\">N</span> 的显存水位，否则回滚本身会触发 OOM；批抖动则通过固定 <span class=\"inline-math\">k</span> 对齐长度缓解，但回退路径会重新引入变长序列，需在调度器侧保留混合批能力。</p>\n<table class=\"mini\"><thead><tr><th>故障</th><th>可观测信号</th><th>系统代价</th><th>处置</th></tr></thead><tbody><tr><td>细粒度误删</td><td>OCR 子集准确率骤降、删除集中于高纹理区</td><td>精度塌陷，整图指标不可见</td><td>上调 k 或换任务相关打分</td></tr><tr><td>预算失配</td><td>精度对 k 回归斜率为正、批内方差大</td><td>显存/带宽随 k 线性增长</td><td>按复杂度分档预算</td></tr><tr><td>顺序错位</td><td>空间关系错误、聚合指标稀释</td><td>难归因，回滚成本高</td><td>保序不变量 + CI 断言</td></tr></tbody></table>\n<h3 id=\"alg-vprune-prelm-sec-46\">四十六 · 同族算法的三条分界线</h3>\n<p>把视觉 token 剪枝的相邻工作放在一张图上，真正决定选型的不是“谁压得更狠”，而是三条分界线：剪枝发生在数据流的哪个位置、重要性信号是否与下游任务耦合、以及是否引入重构或迭代。本算法站在最左端——在视觉编码器输出端、投影层之前做一次性 top-k，打分器与任务解耦。近似误差引导压缩站在另一端，它要构造重构基并计算重构误差，代价是额外的矩阵运算与一次前向；双阶段统一 token 缩减则把剪枝拆成 LLM 之前与中间层两级，收益更大但引入了层间调度与状态传递的复杂度。熵引导视觉剪枝把打分器换成注意力熵，信号更贴任务但需要读到注意力图；逐层视觉 token 压缩把选择推迟到解码器内部，能利用语言侧上下文，却失去了“预填前削减”的最大杠杆。选型的第一步就是问：你的瓶颈到底在预填 FLOPs 还是在解码期 KV 带宽。若在预填，本算法的一次性前置剪枝是最短路径；若在解码且序列极长，逐层方案才有发挥空间。</p>\n<p>第二条分界线是信号来源。本算法的 $s_i=f(\\mathbf{z}_i)$ 只用编码器特征，特征范数、注意力或多样性三者皆可，无需任何标注或校准集，因此可以在多租户服务里对任意可替换的视觉编码器直接挂载。代价写在失败模式里：打分器与任务解耦，细粒度 OCR 与小目标的 token 分数系统性偏低。熵引导与近似误差引导用更强的任务相关信号换来了更高的保留精度，但都需要额外读取中间张量或构造基，部署面变窄。第三条分界线是预算是否自适应：固定 $k$ 让批内序列长度天然对齐，批调度极简；自适应方案按图像复杂度分配预算，精度方差小但批内长度参差，需要 padding 或分桶，吞吐与显存碎片同时上升。</p>\n<div class=\"formula\">$$\\text{keep}=\\text{TopK}\\big(s_i\\big)_{i=1}^{N},\\quad \\frac{M_{\\text{KV}}^{\\text{vis}}}{M_{\\text{KV}}^{\\text{full}}}=\\frac{k}{N}$$</div>\n<p>这条比值式是选型时的第一把尺子：$k/N$ 直接给出视觉 KV 显存的压缩比，也近似给出预填视觉部分算力的压缩比。举例来说，一张高分辨率图编码出数千个 patch token，若 $k$ 取到几百，视觉 KV 占比降到十分之一量级，预填阶段原本被视觉 token 占据的算力让给文本；反过来，若某业务的图像本就只有数百 token，$k/N$ 压不下去多少，前置剪枝的收益被打分器自身开销吃掉，此时应直接放弃剪枝而非硬套。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-47\">四十七 · 决策表：按约束选算法</h3>\n<p>下表把五个同族方案放在同一组工程维度上对照，维度取自真实部署里必须回答的问题，而不是论文里的指标名。表中“信号耦合”指打分是否依赖下游任务或语言侧上下文，“额外前向”指剪枝是否需要在编码器之外再跑一次模型或构造重构基，“预算形态”指 $k$ 是固定还是随图自适应。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>剪枝位置</th><th>信号耦合</th><th>额外前向</th><th>预算形态</th><th>主代价</th></tr></thead><tbody>\n<tr><td>本算法（前置 top-k）</td><td>编码器输出、投影前</td><td>解耦</td><td>无（轻量打分）</td><td>固定 $k$</td><td>细粒度任务误删；简单图过度保留</td></tr>\n<tr><td>近似误差引导压缩</td><td>投影前</td><td>弱耦合（重构误差）</td><td>有（构造基、算误差）</td><td>固定或阈值</td><td>重构算力与显存峰值</td></tr>\n<tr><td>双阶段统一缩减</td><td>投影前 + 中间层</td><td>中耦合</td><td>无</td><td>两级预算</td><td>层间状态传递与调度复杂度</td></tr>\n<tr><td>熵引导视觉剪枝</td><td>投影前</td><td>强耦合（注意力熵）</td><td>需读注意力图</td><td>固定或自适应</td><td>注意力读取的带宽与实现侵入</td></tr>\n<tr><td>逐层视觉 token 压缩</td><td>解码器内部逐层</td><td>强耦合（语言上下文）</td><td>无</td><td>逐层自适应</td><td>失去预填前削减杠杆，实现侵入深</td></tr>\n</tbody></table>\n<p>读表的方式是按约束逐列排除。若部署约束是“训练-free、编码器可替换、多租户”，第一列只剩本算法与逐层方案；再看是否允许改解码器，不允许就只剩本算法。若约束是“OCR 与小目标必须保精度”，则解耦信号直接出局，必须在熵引导或近似误差引导之间选，前者侵入注意力实现，后者吃重构算力，按你的算子库成熟度定。若约束是“预填是瓶颈且图像复杂度方差极大”，固定 $k$ 的精度方差问题会逼你走向双阶段或自适应预算，代价是调度复杂度。这张表没有全局最优，只有约束下的可行集。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-48\">四十八 · 适用条件的量化边界</h3>\n<p>本算法的适用条件可以写成一条不等式：前置剪枝的净收益 = 预填算力与 KV 显存节省 − 打分器开销 − 精度损失带来的重试或降级成本。打分器是轻量算子，其开销与视觉编码器前向同量级偏小，因此在 $k \\ll N$ 时净收益为正；当 $k/N$ 接近 1，节省趋零而打分器开销不变，净收益转负。这条边界给出一个可操作的判据：先测出业务图像的 $N$ 分布，若中位数 $N$ 只有数百，前置剪枝不值得部署；若 $N$ 达数千且文本长度远小于视觉长度，前置剪枝的杠杆最大。</p>\n<p>精度侧的边界由任务类型决定。整图问答、场景描述、图表趋势判断这类任务，被删的 token 多为冗余背景，$k$ 压到较小仍稳定；细粒度 OCR、小目标计数、密集文档字段抽取则相反，被删的恰是承载信息的少数 token，失败是系统性的而非随机的——整图问答正常、局部识别全线崩，离线整图指标看不出来。工程判断是：按任务类型分流量、分 $k$，而不是用一个全局 $k$ 覆盖所有请求。这与负载配方里“图像越复杂越需要更大 $k$”是同一条约束的两面。规模上限也在这里：$k$ 过小则细粒度任务失效，$k$ 过大则收益消失，可扩展性由打分器与任务的相关性封顶，而非由 GPU 档位封顶。</p>\n<div class=\"formula\">$$\\text{net}=c_1\\Big(1-\\frac{k}{N}\\Big)-c_2-\\lambda\\,p_{\\text{fail}}(k,\\text{task})$$</div>\n<p>式中 $c_1$ 为每请求预填与 KV 的单位成本，$c_2$ 为打分器开销，$p_{\\text{fail}}$ 为任务相关的失败概率，$\\lambda$ 为一次失败的代价（重试、人工复核或 SLO 违约）。这个式子不是用来精确计算的，而是用来定性地排序：当 $\\lambda$ 很大（如文档字段抽取的下游是计费系统），任何 $p_{\\text{fail}}$ 的上升都会吞掉算力节省，此时应改用任务相关打分或直接不剪。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-49\">四十九 · 组合而非替代：与量化、缓存的叠加顺序</h3>\n<p>同族算法之间常被当成互斥选项，实际部署里更常见的是叠加，而叠加顺序决定收益能否兑现。本算法与多模态全静态量化的关系是正交的：剪枝削减 token 数，量化削减每 token 的位宽，两者相乘作用于 KV 显存。顺序上必须先剪后量化——若先量化再剪，打分器在低精度特征上算范数，尺度归一化更容易被量化噪声主导，选择稳定性下降。与量化感知视觉剪枝的差别在于后者把剪枝决策纳入量化校准，信号更一致但需要训练或校准流程；本算法训练-free，叠加时应让量化配置与语言模型精度对齐，KV cache 按 $k$ 个视觉 token 分配，而不是按 $N$ 预分配后再裁。</p>\n<p>与视觉缓存复用的叠加则是另一类：缓存复用省的是重复图像的编码与预填，剪枝省的是首次预填。二者叠加时，缓存键必须包含 $k$ 与打分器版本，否则同一图像在不同预算下命中同一缓存条目会返回错误的 token 集合。这是一个容易被忽略的工程细节：剪枝把“图像→token 序列”的映射从确定性变成预算相关，缓存语义随之改变。与跨阶段自适应并行服务的叠加点在于批调度：固定 $k$ 让视觉段长度对齐，分离式预填/解码可以把视觉预填与文本解码放在不同资源池，剪枝后视觉段更短，预填池的占用时间下降，解码池的 KV 带宽压力同步下降。与多模态自适应投机解码叠加时要注意，剪枝改变了视觉上下文长度，草稿模型的接受率会随之漂移，需要按 $k$ 分桶统计而非全局统计。</p>\n\n<h3 id=\"alg-vprune-prelm-sec-50\">五十 · 迁移判断：什么情况下换算法</h3>\n<p>换算法的触发条件应当是观测到的具体现象，而不是“新方案更好”的模糊判断。第一种触发：细粒度任务的失败率在离线评测里不可见但在线上投诉里集中出现，说明解耦打分已到边界，应迁移到熵引导或近似误差引导，用任务相关信号换精度，接受注意力读取或重构算力。第二种触发：批内精度方差随流量组成漂移，单一 SLO 无法覆盖，说明固定 $k$ 对复杂度不敏感已成瓶颈，应迁移到双阶段或自适应预算，代价是调度复杂度与显存碎片。第三种触发：预填已不是瓶颈而解码期 KV 带宽成为主约束，说明前置剪枝的杠杆已用尽，应迁移到逐层压缩，把选择推迟到能读到语言上下文的位置。</p>\n<p>反向迁移同样存在：若你已经在用双阶段方案，但观测到中间层缩减带来的调度开销与状态传递在中小批量下吃掉收益，退回单级前置剪枝是合理判断——两级缩减的收益需要足够大的批与足够长的序列才摊得平。若你已在用熵引导，但注意力读取的实现侵入导致算子融合困难、带宽开销抵消了精度收益，退回本算法的轻量打分并在任务侧分流量，是更稳的工程选择。迁移的成本不只是算法替换，还包括打分器版本管理、缓存键语义变更、以及按 $k$ 分桶的监控重建；这些成本应计入迁移决策，而不是只比较纸面上的压缩比。</p>\n<p>最后落在一条可执行的工程判断上：把 $k$ 从全局常量改成按任务类型与图像复杂度分档的配置项，并在打分器输出上保留空间顺序与尺度归一化，是让本算法在规模上继续可用的最小改动。分档的依据来自线上 $N$ 分布与任务标签，而非离线平均指标；空间顺序的保持决定了位置编码一致性，尺度归一化决定了范数不会单独主导选择。当这两项做到位，前置 top-k 的适用边界就从“整图问答”扩展到“混合流量下的默认档”，而细粒度流量走单独的高 $k$ 通道或迁移到任务相关方案——这正是同族算法选型的落点：不是选一个，而是按流量分层各选一个。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2026 · 视觉Token压缩与合并</td></tr><tr><td>解决什么</td><td>视觉 token 在进入 LLM 前数量巨大（高分辨率图像可达数千），直接送入解码器导致预填算力与 KV cache …</td></tr><tr><td>一句话机制</td><td>在视觉编码器输出端用轻量打分（特征范数/注意力/多样性）做一次性 top-k 选择，只把保留 token 送入 LLM…</td></tr><tr><td>代价与失效</td><td>打分器与下游任务解耦，细粒度 OCR/小目标易被误删；固定预算 k 对简单与复杂图像一视同仁，简单图过度保留</td></tr><tr><td>后继</td><td>近似误差引导压缩</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-vprune-prelm · 共 8 个片段</p>\n";break;}}})();
